export const categories = ["An toàn – An ninh", "FOM – Điều hành khai thác", "An toàn chất lượng", "Dịch vụ", "Phục hồi & Bồi thường"];

export const qaData: QAItem[] = [
  { id: 1, question: "(CÂU 1) Who are authorized for travel in the flight deck with permission but without a possession of a flight deck permit issued by the CAAV or by VNA? CCOM 2.10.1.1(a)", answer: "- Kỹ sư tàu bay đang làm nhiệm vụ\\n- Tổ lái hoặc TV trên chuyến bay positioning\\n- Tổ lái trainee\\n- Nhân viên điều hành khai thác bay đang làm nhiệm vụ\\n- Đánh giá viên đang làm nhiệm vụ", keywords: ["flight deck", "seat", "authorized", "CAAV", "buồng lái", "permit"], category: "An toàn – An ninh" },
  { id: 2, question: "(CÂU 2) Who are authorized for travel in the flight deck with permission and with a possession of a flight deck permit issued by the CAAV or by VNA? CCOM 2.10.1.1(a)", answer: "- Thanh tra bay của Cục HK đang làm nhiệm vụ trên chuyến bay\\n- Chuyên viên/người của Cục đang làm nhiệm vụ trên chuyến bay\\n- Kiểm soát viên không lưu trên chuyến bay cảm giác\\n- Khách hàng đặc biệt được TCT mời lên chuyến bay", keywords: ["flight deck", "permit", "CAAV", "thanh tra", "buồng lái"], category: "An toàn – An ninh" },
  { id: 3, question: "(CÂU 3) Who are permitted to use Cabin Crew Seats? CCOM 2.10.1.2", answer: "Là những người được phép vào buồng lái hoặc nhân viên VNA có thẻ lên máy bay hợp lệ", keywords: ["cabin crew seat", "ghế tiếp viên", "permitted"], category: "An toàn – An ninh" },
  { id: 4, question: "(CÂU 4) In flight deck, what are requirements for vacant crew seat users who are not members of the operating flight or cabin crew? CCOM 2.10.2", answer: "- Ghế phải được trang bị sẵn thiết bị an toàn\\n- Phải mang thẻ bay trong suốt chuyến bay\\n- Được briefing về quy trình an toàn và trang thiết bị tại ghế, quy trình SOP liên quan\\n- Người này phải được tổ bay hoặc tiếp viên thông báo trước giai đoạn cất cánh/hạ cánh và descent\\n- Phải cài dây an toàn trong suốt chuyến bay\\n- PIC sẽ nhấn mạnh tầm quan trọng của việc tránh tiếp xúc hoặc điều chỉnh bất kỳ bộ điều khiển hoặc công tắc nào", keywords: ["flight deck", "vacant seat", "requirements", "ghế trống", "buồng lái"], category: "An toàn – An ninh" },
  { id: 5, question: "(CÂU 5) If an emergency situation develops (such as fire, smoke) during takeoff or landing, what shall cabin crew do? CCOM 2.11.2", answer: "Gọi thẳng lên buồng lái bằng nút EMER trên (A321/A350) hoặc ** (Pilot Alert) trên B787 sau đó sẽ báo cáo TVT", keywords: ["emergency", "fire", "smoke", "takeoff", "landing", "khẩn cấp", "cháy", "khói", "EMER"], category: "An toàn – An ninh" },
  { id: 6, question: "(CÂU 6) When the initial purser or purser in command is inflight rest/incapacitated/not fit for duty, who shall be delegated? CCOM 2.4.3", answer: "- Đối với chuyến bay có chia ca nghỉ, TVT sẽ bàn giao công việc cho TVT còn lại. Trong trường hợp không có TVT, sẽ chỉ định 1 TV senior nhất trong tổ điều hành mọi hoạt động trong khoang khách và phải báo cáo cho PIC\\n- Nếu TVT ngất hoặc mất khả năng điều hành chuyến bay, PIC sẽ là người chỉ định TV senior nhất trong tổ làm vị trí TVT chuyến bay", keywords: ["purser", "incapacitated", "TVT", "senior", "delegation", "ngất", "mất khả năng"], category: "An toàn – An ninh" },
  { id: 7, question: "(CÂU 7) Before unlocking and opening the flight deck door, what must crew member check? CCOM 2.11.3", answer: "- TVT phải kiểm tra và confirm với tổ lái rằng toàn bộ khu vực bên ngoài cửa cockpit clear trước khi yêu cầu vào buồng lái và trước khi rời khỏi buồng lái\\n- Cửa phải được đóng và khoá ngay khi thành viên tổ bay vào hoặc ra khỏi buồng lái\\n- Để vào buồng lái, TVT sẽ gọi lên cockpit qua interphone, sau đó sẽ đọc password đã được thống nhất từ trước mà PIC đã thông báo", keywords: ["flight deck door", "cockpit", "unlock", "password", "interphone", "cửa buồng lái"], category: "An toàn – An ninh" },
  { id: 8, question: "(CÂU 8) During boarding, what should cabin crew do if a disabled passenger happens to seat in an exit row? CCOM 2.13.1.1 f)", answer: "- Đổi chỗ hành khách này sang một ghế khác không phải ghế tại cửa thoát hiểm, sau đó báo cáo TVT\\n- Trường hợp không còn chỗ ngồi xa cửa thoát hiểm, TV phải di chuyển một hành khách khác mà sẵn lòng và có khả năng đảm nhận nhiệm vụ thoát hiểm, vào chỗ ngồi tại hàng ghế ở lối thoát hiểm", keywords: ["disabled", "exit row", "boarding", "khuyết tật", "cửa thoát hiểm", "đổi chỗ"], category: "An toàn – An ninh" },
  { id: 9, question: "(CÂU 9) What is the maximum number of BLND passengers travelling with and without escort on each flight? CCOM 2.13.1.2", answer: "- Có người đi cùng: không giới hạn\\n- Không có người đi cùng: bằng số lượng cửa thoát hiểm của tàu bay", keywords: ["BLND", "blind", "khiếm thị", "escort", "maximum", "giới hạn"], category: "An toàn – An ninh" },
  { id: 10, question: "(CÂU 10) What is the maximum number of DEAF passengers? CCOM 2.13.1.3", answer: "- Có người đi cùng: không giới hạn\\n- Không có người đi cùng: bằng số lượng cửa thoát hiểm của tàu bay", keywords: ["DEAF", "khiếm thính", "escort", "maximum"], category: "An toàn – An ninh" },
  { id: 11, question: "(CÂU 11) What is the maximum number of WCHS passengers? CCOM 2.13.1.6", answer: "- Có người đi cùng: không giới hạn\\n- Không có người đi cùng: bằng số lượng cửa thoát hiểm của tàu bay", keywords: ["WCHS", "wheelchair", "xe lăn", "escort"], category: "An toàn – An ninh" },
  { id: 12, question: "(CÂU 12) What is the maximum number of WCHC passengers? CCOM 2.13.1.6", answer: "- Có người đi cùng: bằng số lượng cửa thoát hiểm của tàu bay\\n- Không có người đi cùng: bằng một nửa số lượng cửa thoát hiểm của tàu bay", keywords: ["WCHC", "wheelchair", "xe lăn", "escort"], category: "An toàn – An ninh" },
  { id: 13, question: "(CÂU 13) What are the regulations of transporting Infants on VNA flights? CCOM 2.13.2.1", answer: "- Chấp nhận vận chuyển INFT khoẻ mạnh, sinh đủ tháng nếu có người đi cùng\\n- Trường hợp có sức khoẻ không bình thường hoặc sinh thiếu tháng → yêu cầu giấy xác nhận sức khoẻ\\n- Không chấp nhận vận chuyển INFT dưới 7 ngày tuổi hoặc phải nuôi trong lồng kính\\n- Dịch vụ TV đi cùng: phải đặt ít nhất 3 ngày trước ngày bay (nội địa) và 5 ngày trước ngày bay (quốc tế)\\n- Số lượng INFT không quá 15% số ghế ngồi\\n- Mỗi người lớn/TV: Max 1 INFT + 1 CHLD dưới 6 tuổi, hoặc Max 2 CHLD dưới 6 tuổi", keywords: ["infant", "INFT", "trẻ sơ sinh", "vận chuyển", "regulations"], category: "An toàn – An ninh" },
  { id: 14, question: "(CÂU 14) What are the regulations of transporting UM on VNA flights? CCOM 2.13.2.2", answer: "- UM là trẻ từ 2-12 tuổi di chuyển không có người giám hộ đi cùng\\n- UM lên máy bay trước các pax khác & không được xếp chỗ ngồi khu vực cửa thoát hiểm\\n- UM (2-4 tuổi) → yêu cầu có dịch vụ TV (1 TV/UM) & ngồi hạng Y\\n- UM (4-6 tuổi) → yêu cầu có dịch vụ TV (1 TV/2 UM) & ngồi hạng Y\\n- UM (6-12 tuổi) → không yêu cầu có dịch vụ TV & ngồi ở tất cả các khoang (total không quá 10% ghế khách nếu ngồi hạng C)\\n- Quy định xếp chỗ: bố trí ngồi gần nhau, không ngồi kế người lớn tuổi, không xếp ngồi hàng ghế dẫn ra lối thoát hiểm", keywords: ["UM", "unaccompanied minor", "trẻ em", "giám hộ"], category: "An toàn – An ninh" },
  { id: 15, question: "(CÂU 15) Seat allocation and handling procedure of Deportee passengers? CCOM 2.12.4", answer: "- Chỗ ngồi phải bố trí ở phía sau cabin, cách xa lối thoát hiểm\\n- Lên trước và xuống sau những hành khách khác\\n- PIC phải được thông báo qua mẫu 'Thông tin đặc biệt cho phi hành đoàn'\\n- Không được phục vụ đồ uống có cồn và các dụng cụ có thể dùng làm vũ khí\\n- Tại điểm đến, TV bàn giao người bị trục xuất cùng với hộ chiếu và mẫu 'Lệnh của người bị trục xuất' cho đại diện", keywords: ["deportee", "trục xuất", "seat allocation", "chỗ ngồi"], category: "An toàn – An ninh" },
  { id: 16, question: "(CÂU 16) What kinds of PEDs are permitted to be used at all times on VNA flights? CCOM 2.20.1", answer: "- Đồng hồ điện tử truyền thống\\n- Máy ghi âm di động truyền thống\\n- Máy trợ thính\\n- Máy hỗ trợ nhịp tim\\n- Máy cạo râu chạy bằng điện\\nQuy định PEDs:\\n- Tất cả PEDs phải chuyển sang FLIGHT MODE và SILENT MODE\\n- PEDs kích thước lớn (>1.3kg) phải cất lên overhead hoặc dưới gầm ghế\\n- Tất cả PEDs không được cắm sạc trong quá trình taxi, cất hạ cánh và dưới 10.000ft\\n** Pin sạc dự phòng - Power Bank:\\n- Cần lấy ra khỏi HLXT và để nơi dễ quan sát\\n- Không để trên overhead locker\\n- Không được sạc từ cổng USB của máy bay", keywords: ["PED", "thiết bị điện tử", "power bank", "pin dự phòng", "flight mode"], category: "An toàn – An ninh" },
  { id: 17, question: "(CÂU 17) How to perform the pre-flight check and operate of a Scott Oxygen bottle? Training Edoc 3.1.2.1", answer: "Pre-flight check:\\n- Số lượng và vị trí - Lấy bình ra khỏi giá đỡ - Áp suất tối thiểu 1500 PSI - Mặt nạ dưỡng khí luôn được kết nối với vòi HI outlet - Không có dầu hoặc mỡ trên thân bình - Dây đeo vai sử dụng được\\nOperation:\\n- Xoay từ từ van điều chỉnh sang vị trí ON - Đảm bảo có oxy trước khi đeo mặt nạ - Đeo mặt nạ cho khách - Sau khi sử dụng, xoay van về vị trí OFF", keywords: ["Scott", "oxygen", "oxy", "bình oxy", "1500 PSI"], category: "An toàn – An ninh" },
  { id: 18, question: "(CÂU 18) How to perform the pre-flight check and operate of a PULSE Oxygen bottle? Training Edoc 3.1.2.1", answer: "Pre-flight check:\\n- Số lượng và vị trí - Van ON/OFF ở vị trí OFF - Đồng hồ áp suất chỉ 1500-1850 PSI - Mặt nạ gắn với bình oxy\\nOperation:\\n- Lấy mặt nạ ra khỏi túi - Vặn van sang vị trí ON (đèn LED sẽ sáng) - Đặt mặt nạ lên mũi và miệng\\nDuration: 180 phút ở chế độ 4 lít", keywords: ["PULSE", "oxygen", "oxy", "bình oxy", "1500-1850 PSI", "180 phút"], category: "An toàn – An ninh" },
  { id: 19, question: "(CÂU 19) How to perform the pre-flight check and operate of Drager Oxycrew PBE? CCOM 5.4.4", answer: "Pre-flight check:\\n- Số lượng và vị trí - Kiểm tra còn seal - Indicator màu VÀNG - Hộp không bị tác động\\nOperation:\\n- Mở hộp và lấy mặt nạ ra khỏi túi bạc - Đội smoke hood lên đầu đảm bảo túi thở ở phía trước ngực - Đảm bảo vòng đệm cổ (neck seal) không có vật cản - Kéo sợi dây đen để kích hoạt oxy - Thắt dây đeo quanh eo\\nDuration: 20 phút", keywords: ["Drager", "PBE", "smoke hood", "indicator vàng", "20 phút"], category: "An toàn – An ninh" },
  { id: 20, question: "(CÂU 20) How to perform the pre-flight check and operate of AVOX system PBE? CCOM 5.4.5", answer: "Pre-flight check:\\n- Kiểm tra còn seal - Moisture indicator màu XÁM (nếu chuyển sang màu PINK thì phải thay hộp mới)\\nOperation:\\n- Mở hộp và lấy mặt nạ - Kéo chốt để kích hoạt oxy (nghe tiếng oxy chảy ra) - Cúi đầu về phía trước, mở rộng neck seal, đội mũ qua mặt và trán\\nDuration: 15 phút", keywords: ["AVOX", "PBE", "smoke hood", "moisture indicator", "15 phút", "PINK"], category: "An toàn – An ninh" },
  { id: 21, question: "(CÂU 21) How to perform the pre-flight check and operate of HALON Type 1? CCOM 5.3.2", answer: "Pre-flight check:\\n- Đồng hồ áp suất GREEN band, plastic seal và safety ring pin vẫn còn nguyên\\nOperation:\\n- Lấy bình ra khỏi giá đỡ - Tháo safety pin - Giữ bình thẳng đứng - Hướng bình về phía gốc ngọn lửa và nhấn chốt (LEVER) xuống để xịt\\nPrecaution:\\n- Không dùng trực tiếp lên người - Giữ khoảng cách 1.5-2m với đám cháy open trong cabin\\nDuration: 12 giây", keywords: ["HALON", "Type 1", "bình chữa cháy", "12 giây", "GREEN band"], category: "An toàn – An ninh" },
  { id: 22, question: "(CÂU 22) How to perform the pre-flight check and operate of HALON Type 2 (Air Total)? CCOM 5.3.4", answer: "Pre-flight check:\\n- Đồng hồ áp suất GREEN band, wire seal và safety latch vẫn còn nguyên\\nOperation:\\n- Giữ bình thẳng đứng - Bẻ SAFE GUARD xuống và remove WIRE SEAL - Nhấn TRIGGER để xịt\\nDuration: 6 giây", keywords: ["HALON", "Type 2", "Air Total", "6 giây", "TRIGGER"], category: "An toàn – An ninh" },
  { id: 23, question: "(CÂU 23) How to perform the pre-flight check and operate of HAFEX (A321-Neo)? Training Edoc 3.2.1.4", answer: "Pre-flight check:\\n- Đồng hồ áp suất GREEN band, safety pin và seal vẫn còn nguyên\\nOperation:\\n- Tháo safety pin - Giữ bình thẳng đứng - Hướng bình về phía gốc ngọn lửa và nhấn chốt (LEVER) xuống để xịt\\nDuration: 9-10 giây", keywords: ["HAFEX", "A321-Neo", "bình chữa cháy", "9-10 giây"], category: "An toàn – An ninh" },
  { id: 24, question: "(CÂU 24) How to perform the pre-flight check and operate of WATER FIRE EXTINGUISHER? Training Edoc 3.2.2", answer: "Description:\\n- Dùng trong đám cháy gỗ, giấy, vải, rác và nhựa\\n- KHÔNG dùng trong đám cháy lỏng hoặc từ nguồn điện\\n- KHÔNG xịt thẳng vào người & không dùng nước trong bình để uống\\nPre-flight check:\\n- Seal chì vẫn còn - Nhìn thấy bình CO2 cartridge qua tay cầm (through the hole)\\nOperation:\\n- Một tay để dưới đáy bình - Vặn tay cầm theo chiều kim đồng hồ để bẻ seal - Giữ bình thẳng đứng, hướng về phía gốc ngọn lửa và nhấn chốt (lever) để xịt", keywords: ["water fire extinguisher", "bình nước chữa cháy", "CO2 cartridge"], category: "An toàn – An ninh" },
  { id: 25, question: "(CÂU 25) How to perform the pre-flight check and launch the LIFE RAFT? CCOM 5.6.4", answer: "Pre-flight check:\\n- Kiểm tra đúng vị trí và số lượng\\n- Đồng hồ áp suất ở vị trí FULL mode hoặc 3-3.5 mbar\\nCapacity: 25-38 người\\nLaunching Raft:\\n- Attach the retaining line to a metal section of the aircraft\\n- Inflate by pulling firmly on the inflation handle\\n- Disconnect the retaining line or cut it with knife provided", keywords: ["life raft", "phao", "launching", "25-38 người"], category: "An toàn – An ninh" },
  { id: 26, question: "(CÂU 26) What is the purpose of the SIGNALLING MIRROR? CCOM 5.7.3.3", answer: "- Gương tín hiệu giúp thu hút sự chú ý trong quá trình tìm kiếm máy bay và tàu thuyền sau khi hạ cánh khẩn cấp bằng cách phản chiếu ánh sáng mặt trời\\n- Tầm xa phản chiếu từ 10-20 km (tuỳ thuộc vào điều kiện thời tiết)", keywords: ["signalling mirror", "gương tín hiệu", "10-20 km"], category: "An toàn – An ninh" },
  { id: 27, question: "(CÂU 27) What is the Emergency Locator Transmitter (ELT) used for? CCOM 5.7.2", answer: "- Bộ phận định vị khẩn cấp (ELT) giúp phát tín hiệu khi máy bay gặp nạn\\n- Pin: 48 tiếng và khoảng cách truyền tín hiệu: 200-250 hải lý\\n- Tần số: 121.5 MHz (dân sự) – 243 MHz (quân sự) – 406 MHz (vệ tinh)", keywords: ["ELT", "emergency locator", "định vị khẩn cấp", "121.5 MHz", "243 MHz", "406 MHz"], category: "An toàn – An ninh" },
  { id: 28, question: "(CÂU 28) KANNAD 406 AS - CCOM 5.7.2.5", answer: "Pre-flight check:\\n- Công tắc ở vị trí ARM\\nOperation:\\n- On water: Tháo dây buộc - Nối móc treo với thuyền phao - Dựng antenna thẳng đứng - Bật công tắc sang ON - Để ELT xuống nước\\n- On land: Tìm vị trí không có obstruction - Chọn vị trí cao nhất - Bật công tắc sang ON - Đặt ELT thẳng đứng", keywords: ["KANNAD", "406 AS", "ELT", "ARM"], category: "An toàn – An ninh" },
  { id: 29, question: "(CÂU 29) ADT 406 - CCOM 5.7.2.7", answer: "Pre-flight check:\\n- Công tắc ở vị trí ARM\\nOperation:\\n- Automatic: Khi máy bay va chạm và công tắc ở vị trí ARM, ELT sẽ được kích hoạt (cũng tự động kích hoạt khi gặp nước)\\n- Manual: Kéo antenna - Bật công tắc sang ON - Đèn LED sẽ sáng để confirm hoạt động", keywords: ["ADT", "406", "ELT", "automatic", "manual"], category: "An toàn – An ninh" },
  { id: 30, question: "(CÂU 30) When hearing 'Cabin crew, cabin system check', what systems does cabin crew have to check? CCOM 3.5.3", answer: "- Cabin Interphone System\\n- Emergency Lighting System (không áp dụng B787)\\n- Passenger call system\\n- Lavatory system (hệ thống chữa cháy tự động – smoke detector – pax call)\\n  → B787: check indicator dots màu TRẮNG\\n- Water/waste system", keywords: ["cabin system check", "interphone", "emergency lighting", "lavatory", "smoke detector"], category: "An toàn – An ninh" },
  { id: 31, question: "(CÂU 31) After hearing 'Cabin crew, security checks', what shall cabin crew do? CCOM 3.6.2", answer: "- TV đến khu vực làm việc chờ khẩu lệnh của TVT\\n- TVT đọc từng mục theo thứ tự 'Danh mục kiểm tra an ninh tàu bay'\\n- TV thực hiện kiểm tra và thumb-up cho TVT sau khi kiểm tra xong\\n- TVT sau khi đọc xong sẽ kiểm tra khu vực của mình\\n- TVT thông báo 'Security check completed' và báo PIC\\nNếu phát hiện vật nghi vấn:\\n- KHÔNG chạm, di chuyển, đổ nước lên\\n- KHÔNG sử dụng thiết bị phát sóng gần\\n- Ghi nhớ đặc điểm, đánh dấu bằng găng tay hoặc cà vạt\\n- Báo ngay PIC và nhà chức trách sân bay", keywords: ["security check", "kiểm tra an ninh", "vật nghi vấn", "thumb-up"], category: "An toàn – An ninh" },
  { id: 32, question: "(CÂU 32) After hearing 'Cabin crew, disarm all slides and cross-check' - A350", answer: "Quy trình 2 TV: một TV đọc checklist, TV còn lại thực hiện:\\n1. TAKE THE SAFETY PIN FROM STOWAGE\\n2. OPEN COVER\\n3. DISARM SLIDE\\n4. INSTALL THE SAFETY PIN\\n5. CLOSE COVER\\n6. DISARM PROCEDURE COMPLETED\\n→ Sau đó thông báo TVT qua Interphone", keywords: ["disarm", "slide", "A350", "safety pin", "cross-check"], category: "An toàn – An ninh" },
  { id: 33, question: "(CÂU 33) After hearing 'Cabin crew, disarm all slides and cross-check' - A321", answer: "Quy trình 2 TV:\\n1. PULL ARMING LEVER\\n2. INSTALL SAFETY PIN\\n3. CHECK INDICATOR GREEN\\n4. DISARM PROCEDURE COMPLETED\\n→ Thông báo TVT qua Interphone", keywords: ["disarm", "slide", "A321", "arming lever", "indicator green"], category: "An toàn – An ninh" },
  { id: 34, question: "(CÂU 34) After hearing 'Cabin crew, disarm all slides and cross-check' - B787", answer: "Quy trình 2 TV:\\n1. OPEN COVER\\n2. DISARM SLIDE\\n3. CHECK INDICATOR ILLUMINATED\\n4. CLOSE COVER\\n5. DISARM PROCEDURE COMPLETED\\n→ Thông báo TVT qua Interphone", keywords: ["disarm", "slide", "B787", "indicator illuminated"], category: "An toàn – An ninh" },
  { id: 35, question: "(CÂU 35) After hearing 'Cabin crew, check cabin and galleys for take off/landing', what shall cabin crew check? CCOM 3.11.1.2", answer: "CHECK CABIN & HÀNH KHÁCH:\\n- Cài dây an toàn, dựng thẳng lưng ghế, gấp bàn ăn, mở tấm che cửa sổ\\n- PEDs phải tuân thủ quy định\\n- Infant cài dây an toàn riêng, nôi phải thu lại trước khi giảm độ cao\\n- Hành lý cất gọn trên overhead hoặc dưới gầm ghế\\n- Màn hình giải trí đóng lại, lối thoát hiểm không có vật cản\\n- Toilet không người và khoá lại\\n- Ban đêm: đèn giảm sáng mức thấp nhất\\nCHECK GALLEY:\\n- Xe đẩy đúng vị trí, đạp phanh, cài chốt khoá\\n- Tủ, máy pha cà phê được secure", keywords: ["check cabin", "galley", "take off", "landing", "dây an toàn", "hành lý"], category: "An toàn – An ninh" },
  { id: 36, question: "(CÂU 36) Khi nào phải kiểm tra An ninh tàu bay? Giáo trình ANHK 6.2.1", answer: "- Trước khi tiếp nhận hành khách, hành lý, hàng hóa lên tàu bay và sau khi xuống hết\\n- Khi có hành khách bỏ chuyến tại điểm khởi hành\\n- Khi khách rời khỏi tàu bay tại điểm quá cảnh, nối chuyến, tạm dừng", keywords: ["kiểm tra an ninh", "security check", "bỏ chuyến", "quá cảnh"], category: "An toàn – An ninh" },
  { id: 37, question: "(CÂU 37) Những đối tượng nào là hành khách tiềm ẩn uy hiếp ANHK?", answer: "- Người bị tâm thần\\n- Người bị từ chối nhập cảnh không tự nguyện về nước\\n- Người bị dẫn độ, bị can, phạm nhân", keywords: ["uy hiếp", "tâm thần", "dẫn độ", "phạm nhân", "an ninh hàng không"], category: "An toàn – An ninh" },
  { id: 38, question: "(CÂU 38) Quy trình xử lý khách gây rối trên chuyến bay? Giáo trình ANHK 7.6.1", answer: "4 MỨC ĐỘ:\\n- Mức độ 1: Xử sự không đúng mực, thái độ đe dọa\\n- Mức độ 2: Hành vi sỉ nhục hoặc tấn công\\n- Mức độ 3: Hành vi đe dọa tính mạng\\n- Mức độ 4: Mưu toan xâm phạm buồng lái\\nCÁCH XỬ LÝ:\\n- Nhắc nhở, giám sát chặt chẽ\\n- TV trực tiếp tiếp xúc để kiềm chế\\n- Khi leo thang: báo PIC, đọc mật khẩu an ninh\\n- TV cảnh cáo khách\\n- Chuyển chỗ khách ra xa cửa thoát hiểm\\n- Không phục vụ đồ uống có cồn, dao muỗng nĩa kim loại\\n- Chọn người trợ giúp (công an, bộ đội)\\n- Có thể khóa tay, bắt giữ nếu đe dọa an toàn máy bay\\n- PIC lập Biên bản VPHC bàn giao cho nhà chức trách", keywords: ["gây rối", "disruptive", "khẩn cấp", "mức độ", "cảnh cáo", "bắt giữ"], category: "An toàn – An ninh" },
  { id: 39, question: "(CÂU 39) Actions in case of Dangerous goods incident on board? CCOM 8.2.1", answer: "Trường hợp có lửa → quy trình chữa cháy Cabin Crew Fire Drill\\nTrường hợp đổ chất lỏng dễ bay hơi/dễ cháy:\\n- Báo PIC tắt nguồn điện trong galley\\n- Khoá cửa cockpit\\n- Tăng hệ thống thông gió tối đa\\n- Chuẩn bị bình Halon\\nNếu không có DGR Kit:\\n- Đeo găng tay chống nóng, bọc túi nhựa\\n- Nếu có khói: đội smokehood, chuẩn bị Halon, di chuyển hành khách\\n- Đặt vật bị rò rỉ vào túi nhựa lớn\\n- Lau sạch, đặt vào túi thứ hai, đóng kín\\n- Đặt vào thùng rác nhà vệ sinh và khóa cửa\\n- Thông báo PIC về các bước đã thực hiện", keywords: ["dangerous goods", "hàng nguy hiểm", "DGR", "rò rỉ", "spillage", "chữa cháy"], category: "An toàn – An ninh" },
  { id: 40, question: "(CÂU 40) 9 Classes of Dangerous Goods - Tài liệu DGR 5.3.1", answer: "LOẠI 1 – CHẤT NỔ (Explosives): 6 nhóm (1.1 đến 1.6)\\nLOẠI 2 – CHẤT KHÍ (Gases): 2.1 dễ cháy, 2.2 không cháy không độc, 2.3 khí độc\\nLOẠI 3 – CHẤT LỎNG DỄ CHÁY\\nLOẠI 4 – CHẤT RẮN DỄ CHÁY: 4.1 rắn dễ cháy, 4.2 tự bốc cháy, 4.3 nguy hiểm khi gặp nước\\nLOẠI 5 – CHẤT OXY HOÁ: 5.1 chất oxy hoá, 5.2 peroxide hữu cơ\\nLOẠI 6 – CHẤT ĐỘC: 6.1 chất độc, 6.2 chất lây nhiễm\\nLOẠI 7 – CHẤT PHÓNG XẠ\\nLOẠI 8 – CHẤT ĂN MÒN\\nLOẠI 9 – CÁC LOẠI HÀNG NGUY HIỂM KHÁC\\n→ Dangerous goods in operator's property: Đá khô, bình oxy, bình halon\\nNhãn nguy hiểm: hình vuông xoay 45 độ, minimum 100x100mm", keywords: ["dangerous goods", "9 classes", "hàng nguy hiểm", "DGR", "chất nổ", "chất khí", "chất lỏng"], category: "An toàn – An ninh" },
  { id: 41, question: "(CÂU 41) INJURY & DEATH ONBOARD - CCOM 2.14", answer: "Dấu hiệu khách đã chết: Tắt thở - Đồng tử giãn - Mạch ngừng đập\\n- TV trợ giúp hợp lý + kêu gọi sự trợ giúp của hành khách có đào tạo y tế\\n- Cơ trưởng quyết định quay lại hoặc hạ cánh sân bay dự bị\\n- Không cho các hành khách khác biết trừ người đi cùng\\n- TV ghi lại chi tiết vào mẫu 'Báo cáo tình trạng sức khoẻ bất thường', lấy chữ ký 2 hành khách làm chứng\\n- Báo cáo gồm 5 liên: cảnh sát sở tại, cơ quan y tế, Đại diện HKVN, Tổ bay, Trung tâm ĐHKT\\n- TV lưu giữ vật phẩm liên quan (thức ăn, đồ uống)\\n- Không di chuyển vị trí người chết", keywords: ["injury", "death", "tử vong", "chết", "đồng tử", "mạch", "báo cáo sức khoẻ"], category: "An toàn – An ninh" },
  { id: 42, question: "(CÂU 42) OPERATION WITH INOPERATIVE DOOR/EXIT - CCOM 4.20", answer: "- Tàu bay có thể khai thác với 1 cửa cabin/exit INOP tuỳ thuộc MEL\\n- Phải briefing hành khách trước khi cất cánh về cửa INOP\\n- TVT đọc PA trước khi hạ cánh đề cập cửa không sử dụng được\\n- TV có thể ngồi tại cửa INOP để giám sát\\n- Trường hợp sơ tán khẩn cấp: TV hướng dẫn hành khách đến cửa có thể sử dụng", keywords: ["inoperative", "door", "exit", "INOP", "MEL", "cửa hỏng"], category: "An toàn – An ninh" },
  { id: 43, question: "(CÂU 43) FIRE PROCEDURE - CCOM 4.3", answer: "Lửa = Oxygen + Heat + Fuel\\nCác nhóm lửa:\\n- Class A: gỗ, giấy, vải → HALON / WATER\\n- Class B: chất lỏng dễ cháy → HALON\\n- Class C: nguồn điện → HALON\\n- Class K: dầu/chất béo → HALON\\nCABIN CREW FIRE DRILL:\\n1/ FireFighter: Xác định nguồn & loại cháy - Tắt nguồn điện - Lấy HALON gần nhất - Lấy smokehood nếu có khói\\n2/ Communicator: Thông báo PIC (ai nói, từ đâu, nguồn cháy, số HALON đã dùng, tình trạng hành khách)\\n3/ Coordinator: Standby thiết bị backup - Di chuyển bình OXY ra xa - Di chuyển hành khách\\n** Nếu chỉ có 2 TV: 1 TV làm đồng thời Communicator + Coordinator", keywords: ["fire", "cháy", "HALON", "firefighter", "communicator", "coordinator", "Class A", "Class B"], category: "An toàn – An ninh" },
  { id: 44, question: "(CÂU 44) DECOMPRESSION - CCOM 4.4.3", answer: "Mặt nạ dưỡng khí tự động rơi:\\n- 14.000 ft (A321/320)\\n- 13.800 ft (A350)\\n- 14.500 ft (B787)\\nDuration: 15 phút (A321/320) / 22 phút (A350) / 60 phút (B787)\\nHành động của TV:\\n- Ở nguyên vị trí, cài dây an toàn, lấy mặt nạ gần nhất\\n- Nếu đang đẩy xe: để xe ngang, đạp phanh, để đồ uống nóng vào xe\\n- Khẩu lệnh: 'Cockpit speaking, emergency descend, cabin crew seated and fastened'\\n- Đợi khẩu lệnh 'Mask off'\\nSau đó:\\n- TVT vào buồng lái kiểm tra tổ lái\\n- TV cầm bình OXY hỗ trợ đồng nghiệp, hành khách\\n- Kiểm tra toilet", keywords: ["decompression", "giảm áp", "mặt nạ dưỡng khí", "14000 ft", "emergency descend"], category: "An toàn – An ninh" },
  { id: 45, question: "(CÂU 45) FAK UPK EMK AED - First Aid Training 7.1", answer: "Số lượng FAK: 0-99 ghế = 1, 100-199 = 2, 200-299 = 3, 300+ = 4\\nEMK: 01 (>30 ghế & FT>=1h)\\nUPK: 01 (0-250 ghế) / 02 (>250 ghế)\\nAED: 01 (A350/B787)\\nPre-flight check:\\n- Kiểm tra seal: XANH (FAK/EMK/AED), WHITE (UPK)\\n- Nếu seal RED → thông báo Cơ trưởng + thợ máy thay hộp mới\\nSau khi sử dụng:\\n- TVT ghi vào logbook: tên khách, tên thuốc, số lượng dùng/còn lại\\n- Điền báo cáo sức khoẻ\\n- Seal bằng seal RED\\n- Ký vào CDL: 'Meet/Fail to meet the operational conditions'", keywords: ["FAK", "UPK", "EMK", "AED", "first aid", "sơ cứu", "seal", "RED", "XANH"], category: "An toàn – An ninh" },
  { id: 46, question: "(CÂU 46) REFUELLING WHEN PASSENGERS REMAIN ON BOARD - CCOM 3.20", answer: "- Số lượng TV còn lại = số cửa thoát hiểm chính\\n- TVT đọc PA thông báo bắt đầu và kết thúc nạp dầu\\n- Hành khách: tháo dây an toàn, không hút thuốc, tắt thiết bị điện tử\\n- Tín hiệu: FSB OFF - NO SMOKING ON - EXIT SIGN ON\\n- Cửa phía trước mở + gắn ống lồng/thang\\n- Cửa 4R ở chế độ ARMED\\n- Các cửa khác DISARMED\\n- Nếu có dấu hiệu cháy/khói → dừng ngay nạp dầu\\n- TV dùng nút EMER hoặc ** (B787) nếu phát hiện bất thường", keywords: ["refuelling", "nạp dầu", "passengers on board", "FSB OFF", "ARMED", "DISARMED"], category: "An toàn – An ninh" },
  { id: 47, question: "(CÂU 47) TURBULENCE - CCOM 3.13", answer: "2 loại: Expected vs Unexpected\\n3 mức độ: Light – Moderate – Severe\\nKhẩu lệnh:\\n- Light: 'All passengers fasten seat belts'\\n- Moderate: 'Cockpit speaking, moderate turbulence, All passengers and crew fasten seat belts'\\n- Severe: 'Cockpit speaking, severe turbulence...'\\nHành động TV:\\n- Visually check dây an toàn, HLXT, PED cất gọn\\n- Infant phải bế ra khỏi nôi\\n- Không phục vụ thức ăn/đồ uống nóng\\n- Secure xe đẩy/container\\n- Moderate: cất chai nước/bình nước nóng vào xe đẩy, TV ngồi cài dây\\n- Severe: dừng toàn bộ dịch vụ, TV ngồi xuống hoặc bám vào thành vách/ghế", keywords: ["turbulence", "nhiễu động", "light", "moderate", "severe", "FSB", "seatbelt"], category: "An toàn – An ninh" },
  { id: 48, question: "(CÂU 48) Xử lý PIN/PEDs cháy/khói trên chuyến bay - CCOM 4.3.12", answer: "PED overheat (không có khói/lửa):\\n- Hướng dẫn khách tắt ngay, ngắt nguồn điện\\n- Không cố tháo pin\\n- Để vị trí dễ quan sát\\nPED rớt/kẹt dưới ghế hạng C (A350/B787):\\n- Báo PIC, dùng găng tay chống nóng để lấy\\n- Đổi chỗ khách, không điều khiển chức năng ghế\\nPin/PED có khói/cháy:\\n- Áp dụng Cabin Crew Fire Drill\\n- Ngắt nguồn điện\\n- Nhúng chìm vào nước/chất lỏng không bắt lửa\\n- Sau 10-15 phút làm mát → lấy container đổ đầy nước, đặt PED vào\\n- Giám sát khu vực thời gian còn lại\\nPin/PED cháy trên overhead:\\n- Fire Drill → di dời hành lý → tiếp cận PED → nhúng nước", keywords: ["PED", "pin", "battery", "cháy", "khói", "overheat", "fire drill"], category: "An toàn – An ninh" },
  { id: 49, question: "(CÂU 49) MINIMUM CABIN CREW - CCOM 2.4", answer: "B787: Long-range overwater = 8, Other = 8/6/5\\nA350: Long-range overwater = 8, Other = 5\\nA321: Long-range overwater = 5, Other = 4\\nA320: Long-range overwater = 5, Other = 4\\nATR 72: N/A, Other = 2", keywords: ["minimum cabin crew", "số lượng TV tối thiểu", "B787", "A350", "A321", "A320", "ATR"], category: "An toàn – An ninh" },
  { id: 50, question: "(CÂU 1) Thời gian bay được tính như thế nào? FOM", answer: "Flight Time: tổng thời gian từ khi máy bay bắt đầu chuyển động khỏi nơi đỗ để cất cánh cho đến khi dừng lại tại điểm kết thúc chuyến bay và tất cả động cơ đều tắt\\n** Maximum FT: 100h/28 ngày liên tiếp và 1000h/12 tháng liên tiếp\\n** FT tối đa dựa trên 2 yếu tố: Giờ có mặt nhận nhiệm vụ và số lần cất hạ cánh", keywords: ["flight time", "thời gian bay", "100h", "1000h", "maximum"], category: "FOM – Điều hành khai thác" },
  { id: 51, question: "(CÂU 2) Thời gian làm nhiệm vụ bay được tính như thế nào? FOM 7.3.2", answer: "Flight Duty Period (FDP): tổng thời gian từ khi TV có mặt nhận nhiệm vụ bay cho đến khi hoàn thành chuyến bay cuối cùng\\nFDP = 1h trước EDT + 15 phút sau khi đóng chèn\\nFDP bao gồm:\\n- Thời gian bay (Flight Time)\\n- Trước chuyến bay (1h trước EDT) và sau chuyến bay (15 phút sau đóng chèn)\\n- Thời gian transit nếu không có chỗ nghỉ phù hợp\\n- Di chuyển deadhead trước chuyến bay\\n- Trực dự bị nếu không có chỗ nghỉ\\nFLIGHT TIME < FLIGHT DUTY PERIOD < DUTY PERIOD", keywords: ["FDP", "flight duty period", "nhiệm vụ bay", "EDT", "đóng chèn"], category: "FOM – Điều hành khai thác" },
  { id: 52, question: "(CÂU 3) Thời gian làm nhiệm vụ được tính như thế nào? FOM", answer: "Duty Period: tổng thời gian từ khi TV được yêu cầu có mặt làm nhiệm vụ đến khi không phải làm bất kỳ nhiệm vụ nào nữa\\n** Maximum DP: 60 giờ/7 ngày liên tiếp & 110 giờ/14 ngày & 190 giờ/28 ngày", keywords: ["duty period", "thời gian làm nhiệm vụ", "60 giờ", "110 giờ", "190 giờ"], category: "FOM – Điều hành khai thác" },
  { id: 53, question: "(CÂU 4) Trực dự bị được tính như thế nào? FOM", answer: "Là khoảng thời gian TV không được giao nhiệm vụ nhưng phải sẵn sàng nhận nhiệm vụ bay. Nếu không nhận được thông báo thì thời gian trực tối đa là 16 tiếng.\\n4 loại trực dự bị (ATCL 4.3.3.2):\\n- Dự bị chuyến bay thường lệ ĐTV R: có mặt P.Briefing 10 phút sau khi nhận điều động\\n- Dự bị tại nhà R.Home: 5 phút xác nhận + có mặt 15 phút\\n- Dự bị thuê chuyến đặc biệt: theo phân công\\n- Dự bị VIPA: dự bị tại ĐTV", keywords: ["trực dự bị", "standby", "reserve", "16 tiếng", "R.Home"], category: "FOM – Điều hành khai thác" },
  { id: 54, question: "(CÂU 4.1) Deadhead transportation - FOM", answer: "- Di chuyển deadhead không được tính là 1 sector\\n- Thời gian di chuyển deadhead được tính là Duty Period (DP)\\n- Di chuyển deadhead sau reporting và trước operating được xem là FDP", keywords: ["deadhead", "di chuyển", "sector", "duty period"], category: "FOM – Điều hành khai thác" },
  { id: 55, question: "(CÂU 5-12) Các bài tập tính thời gian FOM", answer: "VD1: SGN-CXR-SGN cất cánh 10:50, đáp CXR 12:00, chuyển sân CXR-SGN 15:00-16:10 → FT tính từ 10:50-12:00\\nVD2: Chuyển sân SGN-HAN 14:00-16:00 để bay HAN-BKK-HAN 18:00 → 16:15-18:00 là thời gian làm nhiệm vụ bay\\nVD3: SGN-CXR-SGN-DAD + chuyển sân DAD-SGN → quãng 15:16-18:00 là Duty Period\\nCÁC NGUYÊN TẮC:\\n- Thời gian FDP bắt đầu từ 1h trước EDT\\n- Thời gian sau đóng chèn 15 phút là kết thúc FDP\\n- Chuyến bay chuyển sân = Duty Period, không phải FDP\\n- Deadhead trước operating = FDP", keywords: ["bài tập", "tính thời gian", "FDP", "duty period", "SGN", "CXR", "HAN", "DAD"], category: "FOM – Điều hành khai thác" },
  { id: 56, question: "(CÂU 13) Các khoảng thời gian FDP trước và sau nghỉ xen giữa không vượt quá?", answer: "10 giờ và tổng thời gian làm nhiệm vụ bay không vượt quá 20 giờ", keywords: ["nghỉ xen giữa", "split duty", "10 giờ", "20 giờ"], category: "FOM – Điều hành khai thác" },
  { id: 57, question: "(CÂU 14) Thời gian TV có mặt nhận nhiệm vụ đối với chuyến bay thông thường?", answer: "01 giờ trước giờ dự định cất cánh tại máy bay", keywords: ["có mặt", "nhận nhiệm vụ", "1 giờ", "EDT"], category: "FOM – Điều hành khai thác" },
  { id: 58, question: "(CÂU 15-18) Bảng giới hạn FDP theo giờ có mặt và số lần cất hạ cánh - FOM 7.2", answer: "- 14:00-14:29, 4 lần cất hạ cánh → FDP max 11:30\\n- 05:00-05:14, 4 lần → 11:00\\n- 05:15-05:29, 1-2 lần → 12:15\\n- 17:00-04:59, 1-2 lần → 11:00\\n- 15:30-15:59, 4 lần → 10:45\\n- 06:00-13:29, 1-2 lần → 13:00", keywords: ["FDP", "giới hạn", "cất hạ cánh", "bảng 7.2", "thời gian tối đa"], category: "FOM – Điều hành khai thác" },
  { id: 59, question: "(CÂU 19) Giới hạn tổng thời gian bay theo FOM", answer: "Tổng thời gian bay không được vượt quá 100 giờ trong 28 ngày liên tục", keywords: ["giới hạn", "100 giờ", "28 ngày", "tổng thời gian bay"], category: "FOM – Điều hành khai thác" },
  { id: 60, question: "(CÂU 21) Thời gian nghỉ tối thiểu trước khi bắt đầu nhiệm vụ bay?", answer: "Phải bằng thời gian đã làm nhiệm vụ ngay trước đó nhưng không được ít hơn 12 giờ (main base) và 10h (ngoài main base)", keywords: ["nghỉ tối thiểu", "12 giờ", "10 giờ", "main base", "rest period"], category: "FOM – Điều hành khai thác" },
  { id: 61, question: "(CÂU 22) TV cần làm gì khi muốn chuyển sân sớm/muộn hơn?", answer: "Phải làm đơn gửi đến OCC. Làm trái quy định sẽ bị coi là vi phạm kỷ luật. Yêu cầu có thể không được chấp thuận tùy tình hình khai thác.", keywords: ["chuyển sân", "OCC", "đơn", "vi phạm kỷ luật"], category: "FOM – Điều hành khai thác" },
  { id: 62, question: "(CÂU 23) Đơn xin nghỉ phép phải gửi trước ngày nào?", answer: "Không muộn hơn ngày 5 của tháng trước đó", keywords: ["nghỉ phép", "ngày 5", "đơn xin nghỉ"], category: "FOM – Điều hành khai thác" },
  { id: 63, question: "(CÂU 29) Cách tính thời gian bay cho tổ TV tăng cường?", answer: "Thời gian bay của mỗi tiếp viên = (Thời gian bay của chặng bay × số tiếp viên cần thiết cho chuyến bay) / tổng số tiếp viên làm nhiệm vụ", keywords: ["tăng cường", "công thức", "thời gian bay", "augmented"], category: "FOM – Điều hành khai thác" },
  { id: 64, question: "(CÂU 31) Nghỉ phục hồi sau 168 giờ làm nhiệm vụ?", answer: "36 giờ liên tục bao gồm 02 đêm địa phương. Định kỳ 02 lần mỗi tháng, khoảng thời gian nghỉ ngơi hồi phục phải tăng lên bao gồm 02 ngày theo giờ địa phương.\\n(Phải có ít nhất 2 FOM đôi/tháng)", keywords: ["nghỉ phục hồi", "168 giờ", "36 giờ", "FOM đôi", "2 đêm"], category: "FOM – Điều hành khai thác" },
  { id: 65, question: "(CÂU 32) Nghỉ ngơi tối thiểu ngoài căn cứ chính?", answer: "Phải bằng với thời gian làm nhiệm vụ trước đó hoặc không nhỏ hơn 10 giờ (chọn giá trị lớn hơn). Phải bao gồm 08 giờ ngủ + thời gian di chuyển + nhu cầu sinh lý", keywords: ["ngoài căn cứ", "10 giờ", "08 giờ ngủ", "nghỉ ngơi"], category: "FOM – Điều hành khai thác" },
  { id: 66, question: "(CÂU 33) Nhiệm vụ dự bị không tại sân bay?", answer: "Tổng standby không quá 16 giờ. Tổng standby + FDP không vượt quá 18 giờ", keywords: ["standby", "dự bị", "16 giờ", "18 giờ"], category: "FOM – Điều hành khai thác" },
  { id: 67, question: "(CÂU 38) SPLIT DUTY - FOM 7.3.5", answer: "Là khoảng thời gian làm hai nhiệm vụ bay bị ngắt quãng bằng một khoảng nghỉ xen giữa\\n- Thời gian nghỉ dưới mặt đất tối thiểu 3 giờ liên tục\\n- Split duty không được tính vào in-flight rest\\n- Thời gian nghỉ được tính đầy đủ như FDP\\n- Công thức kéo dài FDP: Max planned FDP = Max FDP trong bảng 7.2 + 50% Break Time", keywords: ["split duty", "nghỉ xen giữa", "3 giờ", "50%", "break time"], category: "FOM – Điều hành khai thác" },
  { id: 68, question: "(CÂU 41) Quy định về ngày nghỉ (day off)?", answer: "- Tối đa 03 ngày/1 lần\\n- Gửi chậm nhất ngày mùng 5 tháng trước\\n- Tối đa 06 lần yêu cầu/1 năm", keywords: ["day off", "ngày nghỉ", "03 ngày", "06 lần/năm"], category: "FOM – Điều hành khai thác" },
  { id: 69, question: "(CÂU 44) Quy định báo ốm và giám định sức khoẻ? FOM 7.2.2", answer: "- TV báo ốm tối thiểu 4h trước EDT (main base) và 1h trước Standby\\n- Ngoài mainbase: tối thiểu 12h trước EDT\\n- TV đi giám định lại sức khoẻ nếu:\\n  + Báo ốm >= 3 lần/30 ngày liên tục\\n  + Báo ốm > 20 ngày/lần", keywords: ["báo ốm", "giám định", "4h", "12h", "sức khoẻ"], category: "FOM – Điều hành khai thác" },
  { id: 70, question: "(CÂU 1) TCT HKVN và ĐTV thành lập ngày nào? ATCL 2.1.1", answer: "- TCT Hàng không VN: 27/5/1995\\n- Đoàn Tiếp viên: 01/6/1993 theo quyết định số 439/CAAV", keywords: ["thành lập", "27/5/1995", "01/6/1993", "ĐTV", "HKVN"], category: "An toàn chất lượng" },
  { id: 71, question: "(CÂU 2) Chức năng của ĐTV? ATCL 2.1.3", answer: "ĐTV có chức năng quản lý và cung cấp tiếp viên trực tiếp tham gia các hoạt động khai thác và dịch vụ trên không phục vụ hành khách trên chuyến bay của TCTHK", keywords: ["chức năng", "ĐTV", "quản lý", "cung cấp tiếp viên"], category: "An toàn chất lượng" },
  { id: 72, question: "(CÂU 3) Nhiệm vụ của TV là gì?", answer: "- Đảm bảo an toàn, an ninh cho chuyến bay\\n- Chăm sóc, phục vụ hành khách\\n- Thỏa mãn tốt nhất nhu cầu của hành khách", keywords: ["nhiệm vụ", "an toàn", "an ninh", "phục vụ"], category: "An toàn chất lượng" },
  { id: 73, question: "(CÂU 4-5) Chu trình phát triển và Chương trình đào tạo TVHK - ATCL 5.1-5.2", answer: "Chu trình: TVY → TVC → TVT Bậc 1 → TVT Bậc 2 → Kiểm tra viên DV\\nChương trình đào tạo: Huấn luyện ban đầu → Huấn luyện định kỳ → Nâng bậc → Phục hồi → Chuyển nhà khai thác → Nâng cao nghiệp vụ", keywords: ["chu trình", "phát triển", "đào tạo", "TVY", "TVC", "TVT", "nâng bậc"], category: "An toàn chất lượng" },
  { id: 74, question: "(CÂU 6-13) Tiêu chuẩn giờ bay và tiếng Anh xét chọn nâng bậc - ATCL", answer: "TVY → TVC (thường): 1500h bay Y + TOEIC 650\\nTVY → TVC (fast track): 1000h bay Y + TOEIC 750\\nTVC → P1 (thường): 3 năm + 1500h bay C + TOEIC 700\\nTVC → P1 (fast track): 3 năm + 1200h bay C + TOEIC 750\\nP1 → P2 (thường): 2000h bay P1 + TOEIC 700\\nP1 → P2 (fast track): 1500h bay P1 + TOEIC 750\\nP2 → GVDV (thường): 2000h bay P2 + TOEIC 700\\nP2 → GVDV (fast track): 1500h bay P2 + TOEIC 750", keywords: ["nâng bậc", "TOEIC", "giờ bay", "fast track", "TVY", "TVC", "P1", "P2"], category: "An toàn chất lượng" },
  { id: 75, question: "(CÂU 14) Tiêu chuẩn xét nhóm 1 - ATCL", answer: "- Bay tích luỹ 360h\\n- TOEIC >= 550\\n- Hoàn thành chương trình phát triển năng lực TVY\\n- Đạt chuẩn hoá từ 80/100\\n- REC ATB + DV + Chuyển loại tàu bay không thi trượt từ 2 lần cộng dồn trở lên", keywords: ["nhóm 1", "360h", "TOEIC 550", "chuẩn hoá", "80/100"], category: "An toàn chất lượng" },
  { id: 76, question: "(CÂU 15) Quy định xuống nhóm 2 - ATCL", answer: "01 tháng: Nghỉ VR liên tục 2-6 tháng\\n02 tháng: Nghỉ VR > 6 tháng / Thi trượt REC lần 2 / Báo ốm >= 3 lần/tháng / Vi phạm lớp học >= 2 lần/12 tháng\\n03 tháng: Thi trượt lần 3 hoặc <50 điểm / Không đạt chuẩn hoá 70-80/100\\n06 tháng: Kỷ luật Khiển trách / Chuẩn hoá 60-70/100\\n12 tháng: Kỷ luật Kéo dài nâng lương, cách chức", keywords: ["nhóm 2", "xuống nhóm", "thi trượt", "kỷ luật", "chuẩn hoá"], category: "An toàn chất lượng" },
  { id: 77, question: "(CÂU 16) Vi phạm kỷ luật không đủ tiêu chuẩn xét nâng bậc?", answer: "Vi phạm nội quy lao động mức Khiển trách (hoặc 02 Phê bình hoặc 04 Nhắc nhở) trở lên trong vòng 1 năm tính đến ngày đề cử nâng bậc hoặc ngày tham gia kiểm tra", keywords: ["kỷ luật", "nâng bậc", "khiển trách", "phê bình", "nhắc nhở"], category: "An toàn chất lượng" },
  { id: 78, question: "(CÂU 17-18) Trang phục khi bay DEH - ATCL", answer: "Bay DEH theo danh sách hành khách: mặc thường phục lịch sự, tuyệt đối không mặc hở hang, mỏng/trong suốt, phản cảm, váy quá ngắn, quần short, dép lê/dép kẹp\\nBay DEH theo danh sách tổ bay (GD): mặc đồng phục khi check-in, boarding. Trên máy bay thay thường phục lịch sự sau khi khách boarding xong", keywords: ["DEH", "deadhead", "trang phục", "đồng phục", "thường phục"], category: "An toàn chất lượng" },
  { id: 79, question: "(CÂU 19) Giấy tờ, trang thiết bị TV phải mang theo khi bay?", answer: "- CMC - Thẻ bay - Hộ chiếu\\n- Chứng chỉ huấn luyện (An toàn, An ninh, DGR, First Aid, CRM, FRMS, SMS) (Bản giấy + E-Certificate)\\n- Chứng chỉ sức khoẻ\\n- IPAD >70% pin + cài đặt MO Plus", keywords: ["giấy tờ", "CMC", "thẻ bay", "hộ chiếu", "chứng chỉ", "IPAD"], category: "An toàn chất lượng" },
  { id: 80, question: "(CÂU 20) Khi bị ốm, TV cần nộp loại giấy nghỉ ốm nào?", answer: "- Giấy nghỉ ốm hưởng BHXH của cơ sở y tế có thẩm quyền\\n- Giấy ra viện\\n- Giấy cấp cứu\\n- TV bị ốm ở nơi không có cơ sở y tế BHYT → nộp giấy khám + biên lai thu phí\\n- Các loại giấy ốm phải bằng Tiếng Việt hoặc Tiếng Anh", keywords: ["giấy nghỉ ốm", "BHXH", "giấy ra viện", "cấp cứu"], category: "An toàn chất lượng" },
  { id: 81, question: "(CÂU 22) TV bị đình bay trong trường hợp nào? ATCL", answer: "- Xác minh vi phạm kỷ luật/pháp luật\\n- Mất thẻ bay, bằng cấp, chứng chỉ\\n- Không đạt yêu cầu ATB, line check, DV, ngoại ngữ\\n- Không đạt yêu cầu ngoại hình\\n- Không đủ tiêu chuẩn sức khỏe\\n- Trong thời gian đình bay, TV có thể làm việc mặt đất", keywords: ["đình bay", "vi phạm", "mất thẻ", "ngoại hình", "sức khoẻ"], category: "An toàn chất lượng" },
  { id: 82, question: "(CÂU 23-25) Quy định trực dự bị và vi phạm - ATCL", answer: "- Xác nhận nhiệm vụ trong 5 phút, có mặt P.Briefing 10 phút (trực ĐTV) / 15 phút (R.Home)\\n- Trực dự bị muộn 15-30 phút hoặc đến chậm 10-20 phút → NHẮC NHỞ\\n- Không xác nhận khi báo ốm → NHẮC NHỞ", keywords: ["trực dự bị", "nhắc nhở", "vi phạm", "xác nhận"], category: "An toàn chất lượng" },
  { id: 83, question: "(CÂU 26) Mang vận chuyển hàng hoá ngoài đồng phục → mức xử lý?", answer: "Kéo dài thời hạn nâng lương 6 tháng (ATCL 6.12.5.4)", keywords: ["hàng hoá", "vận chuyển", "kỷ luật", "nâng lương"], category: "An toàn chất lượng" },
  { id: 84, question: "(CÂU 27) Đội hình TV di chuyển trong nhà ga - TCPV 1.3.3.2", answer: "- TV <= 8: TVT → TV nữ → TV nam\\n- TV > 8: chia 2 hàng\\n- Khoảng cách 1m\\n- TVT bậc 1 là nam sẽ đi sau cùng giám sát\\n- Vali để cùng 1 phía", keywords: ["đội hình", "di chuyển", "nhà ga", "TVT", "vali"], category: "An toàn chất lượng" },
  { id: 85, question: "(CÂU 28) TV được rời máy bay vào nhà ga tại nước ngoài khi nào?", answer: "- Chuyến bay cất hạ cánh đúng giờ (nếu delay thì không được)\\n- PIC không yêu cầu ở lại\\n- Số TV vào nhà ga không quá 1/2 tổ\\n- GT > 1h15, quay lại ít nhất 60 phút trước cất cánh\\n- Nhật-Hàn: GT > 1h30, quay lại ít nhất 60 phút trước", keywords: ["nhà ga", "nước ngoài", "rời máy bay", "ground time", "Nhật", "Hàn"], category: "An toàn chất lượng" },
  { id: 86, question: "(CÂU 29) Quy định rời khỏi nơi nghỉ tập trung?", answer: "- Phải có sự đồng ý của TVT\\n- Trở về trước 23:00 địa phương\\n- Trước giờ rời nơi nghỉ ít nhất 08 giờ\\n- Không nghỉ qua đêm: phải được Cán bộ liên đội cho phép bằng văn bản", keywords: ["nơi nghỉ", "tập trung", "23:00", "08 giờ", "văn bản"], category: "An toàn chất lượng" },
  { id: 87, question: "(CÂU 30) TV phục vụ hạng Y đánh giá TV nào?", answer: "- P2 đánh giá: P1 + C + Y (A350/B787)\\n- P1 đánh giá: P2 + Y (A350/B787)\\n- P đánh giá: C + Y (A321)\\n- C đánh giá: P2 (A350/B787) + P (A321) + TVC (A350/B787)\\n- Y đánh giá: P1 (A350/B787) + P (A321)", keywords: ["đánh giá", "line check", "P1", "P2", "TVC", "TVY"], category: "An toàn chất lượng" },
  { id: 88, question: "(CÂU 31) Nội dung & Thời gian họp Briefing?", answer: "- Chào hỏi, kiểm tra hành lý, đồng phục, diện mạo, bằng cấp, chứng chỉ\\n- Triển khai thông tin chuyến bay\\n- Kiểm tra taskcard theo Cabinbook\\n- Review AT-AN\\n- Triển khai quy trình dịch vụ\\n- Đặt mục tiêu chuyến bay\\nThời gian: 20 phút (nội địa + quốc tế ngắn) / 25 phút (quốc tế trung dài)", keywords: ["briefing", "họp", "taskcard", "cabinbook", "20 phút", "25 phút"], category: "An toàn chất lượng" },
  { id: 89, question: "(CÂU 32) Danh mục tài liệu TVT mang theo chuyến bay?", answer: "- Danh mục kiểm tra An ninh tàu bay\\n- Mẫu bàn giao vụ việc\\n- Biên bản vụ việc\\n- Phiếu MCO bồi thường\\n- Phiếu phục hồi và đảm bảo dịch vụ\\n- Báo cáo sức khoẻ bất thường hành khách\\n- Pax Order (hạng C)\\n- DO NOT OFFLOAD\\n- Sticker Unserviceable Return\\nBổ sung theo tuyến: KHH/TPE tờ khai nhập cảnh, LHR khai báo HQ online, SYD/MEL/PER tờ khai HQ, FRA phiếu niêm phong xe rượu", keywords: ["tài liệu", "TVT", "MCO", "phiếu bồi thường", "biên bản"], category: "An toàn chất lượng" },
  { id: 90, question: "(CÂU 33) Quy định đình bay - ATCL 4.6.1", answer: "Đình bay = không phân công TV thực hiện nhiệm vụ bay, áp dụng:\\n- Xác minh vi phạm pháp luật/kỷ luật\\n- Mất thẻ bay, bằng cấp, chứng chỉ\\n- Không đạt ATB, rec, line check, DV, ngoại ngữ\\n- Không đạt ngoại hình: mặt mụn, trầy xước, sẹo, BMI\\n- Không đủ sức khoẻ\\n- Trong thời gian đình bay, TV có thể làm việc mặt đất", keywords: ["đình bay", "vi phạm", "thẻ bay", "BMI", "ngoại hình"], category: "An toàn chất lượng" },
  { id: 91, question: "(CÂU 34-35) Vi phạm và không hoàn thành công việc?", answer: "- 3 thông báo 'Không hoàn thành công việc' trong 6 tháng → xem xét chấm dứt hợp đồng\\n- Bị kỷ luật PHÊ BÌNH nếu:\\n  + Đi muộn 10-20 phút\\n  + Thi trượt 2 lần/6 tháng\\n  + Nghỉ học/về sớm 15-45 phút", keywords: ["không hoàn thành", "chấm dứt hợp đồng", "phê bình", "vi phạm"], category: "An toàn chất lượng" },
  { id: 92, question: "(CÂU 36) Quy định đánh giá Line Check?", answer: "- Mỗi TV đánh giá 3 năm/lần (2 chặng bay) theo IOSA\\n- 20 nội dung đánh giá\\n- TVT đánh giá tối đa 2 TV/chuyến trên Cabinbook\\n- YES = PASSED hoặc N/A → ĐẠT\\n- 1 tiêu chí NO = FAILED → KHÔNG ĐẠT\\n- Không đạt lần 1 → LC lại lần 2 (tự trả chi phí)\\n- Không đạt lần 2 → cắt bay, huấn luyện lại ATB (tự trả chi phí)", keywords: ["line check", "IOSA", "đánh giá", "3 năm", "20 nội dung"], category: "An toàn chất lượng" },
  { id: 93, question: "(CÂU 37) Quy định hạ bậc TV?", answer: "- Đình bay 02 lần do không đạt rec ATB/DV\\n- Bỏ học/bỏ thi không lý do\\n- Kỷ luật kéo dài nâng lương/cách chức\\n- Bị khiển trách theo Hội đồng xem xét\\n- Quản lý để TV vi phạm gây hậu quả nghiêm trọng\\n- Không đạt BMI hoặc TOEIC\\n- Chuẩn hoá < 60 điểm\\n- Lý do cá nhân", keywords: ["hạ bậc", "đình bay", "khiển trách", "BMI", "chuẩn hoá"], category: "An toàn chất lượng" },
  { id: 94, question: "(CÂU 38) Lãnh đạo Vietnam Airlines?", answer: "- Chủ tịch HĐQT: Mr. ĐẶNG NGỌC HÒA\\n- Tổng Giám Đốc: Mr. LÊ HỒNG HÀ\\n- Phó TGĐ: Mr. Nguyễn Chiến Thắng / Tô Ngọc Giang / Đinh Văn Tuấn / Nguyễn Thế Bảo / Lê Đức Cảnh / Đặng Anh Tuấn", keywords: ["lãnh đạo", "VNA", "chủ tịch", "tổng giám đốc", "phó TGĐ"], category: "An toàn chất lượng" },
  { id: 95, question: "(CÂU 39) TVT viết Báo cáo chuyến bay?", answer: "Trên Cabinbook:\\n- Tất cả sự cố ATAN\\n- Báo cáo tự nguyện/bí mật trên AQD (sms.vietnamairlines.com)\\nThời hạn: NGAY LẬP TỨC (phòng ATCL) + KHÔNG QUÁ 1 GIỜ (Cabinbook/AQD):\\n- Mức A: Tai nạn tàu bay\\n- Mức B: Sự cố nghiêm trọng\\n- Mức C/D: Nguy cơ uy hiếp AT\\n- Mức E: Vụ việc (không quá 24h)\\nBCCB trong 8 giờ: sự việc VIP, nhiều khách không hài lòng, nguy cơ MXH, ảnh hưởng DV, delay 15 phút+, lỗi TV\\nBCCB trong 24 giờ: kiến nghị, thái độ hợp tác", keywords: ["báo cáo", "cabinbook", "AQD", "BCCB", "sự cố", "thời hạn"], category: "An toàn chất lượng" },
  { id: 96, question: "(CÂU 40) Quy định sử dụng mạng xã hội (MXH)?", answer: "- Chịu trách nhiệm cá nhân về nội dung đăng tải\\n- Tuân thủ quy định pháp luật, an ninh thông tin, bảo mật\\n- KHÔNG phát ngôn đi ngược nguyên tắc VNA\\n- KHÔNG gây bất lợi/tổn hại uy tín VNA\\n- KHÔNG lợi dụng danh nghĩa VNA cho mục đích cá nhân\\n- KHÔNG đăng ảnh đồng phục để quảng cáo/bán hàng/chỉ trích\\n- KHUYẾN KHÍCH: chia sẻ thông tin chính thức VNA, sản phẩm, sự kiện\\n- Nếu được phỏng vấn: báo cáo LĐTV, nội dung phải được Tổ Truyền thông duyệt", keywords: ["mạng xã hội", "MXH", "facebook", "đăng tải", "hình ảnh", "đồng phục"], category: "An toàn chất lượng" },
  { id: 97, question: "SKYHOME – NGÔI NHÀ CỦA TRÁI TIM HIẾU KHÁCH (HEART)", answer: "H – Hospitality: Thể hiện lòng hiếu khách nồng hậu, chào đón niềm nở, chăm sóc tận tâm\\nE – Elegant Cabin: Kiến tạo không gian máy bay đẹp ấm cúng và sang trọng\\nA – Appearance: Chăm sóc ngoại hình, đồng phục sáng đẹp, phong thái chuyên nghiệp\\nR – Responsive Presence: Sẵn sàng chủ động, hiện diện đúng lúc, phục vụ trước khi khách yêu cầu\\nT – Treasure The Aircraft: Trân trọng tài sản và giữ gìn máy bay như ngôi nhà của mình", keywords: ["SKYHOME", "HEART", "hospitality", "elegant", "appearance", "responsive"], category: "Dịch vụ" },
  { id: 98, question: "(DV CÂU 1) Suất ăn đặc biệt SPML - Các loại", answer: "AVML: ăn chay Hindu/châu Á (không thịt, cá, trứng)\\nMOML: đạo Hồi (không thịt lợn, rượu)\\nHNML: đạo Hindu (không bò, bê, lợn, cá sống)\\nVJML: đạo Jain (không thịt, cá, trứng, sữa, củ/rễ)\\nVLML: ăn chay có trứng sữa\\nVOML: ăn chay phương Tây (không thịt, cá)\\nVGML: ăn chay thuần (không sản phẩm động vật)\\nSFML: hải sản\\nCHML: trẻ em 2-5 tuổi\\nBBML: trẻ dưới 2 tuổi\\nFPML: không chất phụ gia/bảo quản\\nRVML: ăn chay rau quả\\nLCML: ít calo (<400 calo/bữa)\\nLSML: kiểm soát natri\\nLFML: ít chất béo\\nNLML: không đường lactose\\nDBML: tiểu đường\\nBLML: bệnh đường ruột/dạ dày\\nGFML: dị ứng gluten\\nKSML: đạo Do Thái\\nHFML: chất xơ cao\\nĐặt dịch vụ: website VNA, 'Quản lý đặt chỗ', hoặc gọi 19001100 trước 24h", keywords: ["SPML", "AVML", "MOML", "HNML", "VJML", "VLML", "VGML", "SFML", "CHML", "BBML", "FPML", "RVML", "LCML", "LSML", "LFML", "NLML", "DBML", "BLML", "GFML", "KSML", "HFML", "suất ăn đặc biệt"], category: "Dịch vụ" },
  { id: 99, question: "(DV CÂU 2) Lưu ý khi mời thực đơn hạng C - TCPV 4.1.6", answer: "- Chuẩn bị thực đơn đúng tuyến đường bay, bữa ăn\\n- Danh mục thức uống kẹp giữa trang thực đơn\\n- Cầm tối đa 10 cuốn/lần (thực tế 3 bộ/chặng)\\n- Mở sẵn thực đơn ngôn ngữ phù hợp\\n- Giới thiệu menu food/drink list - Mời tham khảo - Thông báo thời điểm nhận yêu cầu - Xác nhận SPML nếu có", keywords: ["thực đơn", "menu", "hạng C", "giới thiệu", "SPML"], category: "Dịch vụ" },
  { id: 100, question: "(DV CÂU 3) Rượu Cognac - nguyên liệu, nồng độ, cách phục vụ?", answer: "- Chưng cất từ rượu vang nho, ủ trong thùng gỗ sồi Limousin ít nhất 2 năm\\n- Nồng độ cồn: 40%\\n- Phân loại: V.S (★★★, ≥2 năm), V.S.O.P (≥4 năm, VNA đang dùng trên hạng C), X.O/Napoleon (≥6 năm)\\n- Phục vụ bằng ly Brandy, mời cùng món tráng miệng\\n- Uống nguyên chất, không pha/thêm đá, rót hết 1 chai nhỏ (~25ml)", keywords: ["cognac", "rượu", "brandy", "VSOP", "XO", "40%", "gỗ sồi"], category: "Dịch vụ" },
  { id: 101, question: "(DV CÂU 4) Phục vụ khách khiếm thị BLND?", answer: "Boarding:\\n- TV đi trước khách BLND\\n- Chỉ hướng trái/phải theo hướng đi khách, đặt tay khách lên tay/lưng ghế\\n- Hỗ trợ cất/trả HLXT\\nPhục vụ:\\n- Hạn chế hỏi câu hỏi cần thị giác\\n- Giới thiệu món bằng cách gọi tên hoặc chạm nhẹ vào tay khách\\n- Lưu ý đồ uống nóng\\n- Xin phép mở bộ dao muỗng dĩa", keywords: ["BLND", "khiếm thị", "blind", "phục vụ", "hướng dẫn"], category: "Dịch vụ" },
  { id: 102, question: "(DV CÂU 5) Phục vụ khách khiếm thính DEAF?", answer: "- Giao tiếp bằng ngôn ngữ biểu thị rõ ràng hoặc chữ viết\\n- Kiên nhẫn, phát âm rõ ràng, chỉ nói to khi cần\\n- Không phục vụ tai nghe", keywords: ["DEAF", "khiếm thính", "giao tiếp", "chữ viết"], category: "Dịch vụ" },
  { id: 103, question: "(DV CÂU 6) Phục vụ khách UM trên chuyến bay?", answer: "- UM 2-6 tuổi: cần TV đi cùng\\n- UM 6-12 tuổi: không cần TV đi cùng, TV đi lại trợ giúp khi có yêu cầu\\n- TVT nhận bàn giao UM từ NVM, giao TV phụ trách\\n- Hướng dẫn: dây an toàn, áo phao, nút gọi TV, nhà vệ sinh\\n- Nhắc UM cuối chuyến ngồi yên, xuống sau\\n- Bàn giao UM cho NVMĐ", keywords: ["UM", "trẻ em", "unaccompanied minor", "TV đi cùng"], category: "Dịch vụ" },
  { id: 104, question: "(DV CÂU 7) Phục vụ khách WCHC? PHM 7.1.9.7", answer: "- TV hỗ trợ khách WCHC di chuyển trong khoang khách nếu khách yêu cầu\\n- Không lắp và phục vụ xe lăn khi cất/hạ cánh và turbulence\\n- Sau khi bay bằng: chuẩn bị xe lăn hỗ trợ khách (đến nhà vệ sinh)\\n- Trước hạ cánh: cất xe lăn đúng vị trí", keywords: ["WCHC", "xe lăn", "wheelchair", "di chuyển"], category: "Dịch vụ" },
  { id: 105, question: "(DV CÂU 8) Bán hàng miễn thuế BHMT - TBDV 277M", answer: "Giao nhận đầu chuyến:\\n- Check số seal, ổ khoá 2 đầu, nhận chìa khoá\\n- Mở seal túi tiền: ĐI XÁM / VỀ CAM ($50 sẵn)\\n- Kiểm tra máy POS + máy PAYOO\\nCách mở POS: Password mở máy 1956/1957, Đăng nhập MSNV 6430 / Password 12345678\\nGiấy tờ nộp ĐTV: Phiếu bàn giao xe BHMT, Phiếu liệt kê thiết bị, Phiếu kê tiền mặt", keywords: ["BHMT", "miễn thuế", "duty free", "POS", "1956", "1957", "seal", "túi tiền"], category: "Dịch vụ" },
  { id: 106, question: "(DV CÂU 9-10) Cách chuẩn bị, phục vụ bánh mì?", answer: "Bánh mì sáng (Croissant, Pastry):\\n- Làm nóng lò 3 phút, nướng Dryheat 3-5 phút, nướng ngoài túi\\nCác loại bánh mì khác:\\n- Bánh mì tỏi & baguette → Dryheat 5-6 phút\\n- Croissant/chocolate/tròn/cuộn/Danish → Dryheat 3-5 phút\\n** Không cần nướng: bánh mì hạt, bột chua, champion, đen, Ciabatta, nguyên cám, vừng, Muffin socola", keywords: ["bánh mì", "croissant", "pastry", "baguette", "nướng", "Dryheat"], category: "Dịch vụ" },
  { id: 107, question: "(DV CÂU 11) Hỗ trợ khách nối chuyến bị trễ?", answer: "- Tiếp cận và tiếp nhận thông tin: số hiệu CB tiếp theo, giờ cất cánh, điểm đến\\n- Đổi chỗ khách lên hàng ghế phía trước (theo hạng ghế) nếu còn chỗ\\n- TVT thông báo NVMĐ/Đại diện VNA để hỗ trợ thủ tục", keywords: ["nối chuyến", "trễ", "connecting flight", "đổi chỗ"], category: "Dịch vụ" },
  { id: 108, question: "(DV CÂU 12) Thứ tự ưu tiên mời thức ăn/thức uống?", answer: "Mời: từ trong ra ngoài. Ưu tiên: người cao tuổi → người khuyết tật → trẻ em → phụ nữ\\nThu khay: thu từ ngoài vào trong", keywords: ["ưu tiên", "mời", "thu khay", "thứ tự phục vụ"], category: "Dịch vụ" },
  { id: 109, question: "(DV CÂU 13) Vị trí lắp nôi và quy định? PHM 7.1.4", answer: "- Đặt dịch vụ BSCT ít nhất 24h trước EDT\\n- Chấp nhận trẻ < 11kg và dưới 2 tuổi\\n- Vị trí: Đầu khoang C (A321), Đầu khoang C/PE/Y (A350/B787)\\n- Nôi lắp sau cất cánh (seatbelt sign OFF)\\n- Nôi tháo khi giảm độ cao để hạ cánh\\n- Infant bế ra khỏi nôi khi thời tiết xấu và seatbelt sign ON", keywords: ["nôi", "BSCT", "bassinet", "infant", "11kg"], category: "Dịch vụ" },
  { id: 110, question: "(DV CÂU 14) Quy định nhiệt độ khoang khách? TCPV 3.2.1", answer: "Trước khi khách lên: 22°C (mùa hè) / 25°C (mùa đông)\\nTrong chuyến bay: 24-25°C (nội địa + quốc tế ngắn), 23-24°C (quốc tế dài/trung)\\nNếu khoang lạnh: TV báo TVT điều chỉnh → hỏi thăm sức khoẻ khách → offer nước ấm, áo khoác, van khí, chăn", keywords: ["nhiệt độ", "khoang khách", "22°C", "25°C", "24-25°C", "23-24°C"], category: "Dịch vụ" },
  { id: 111, question: "(DV CÂU 15) Phục vụ mỳ/phở hạng Y? TCPV 3.1.20", answer: "KHÔNG phục vụ đồ nóng khi: turbulence + FSB ON, bàn ăn hỏng, đèn cá nhân hỏng khi đèn trần tắt\\nChuẩn bị:\\n- Mở ly mỳ/phở, thêm gia vị, bỏ gói dầu\\n- Cho nước sôi 1/2 ly ngập phần mỳ\\n- Đậy nắp 3-5 phút, trộn đều\\n- Cho nước suối nguội (mực nước cách miệng ly 3cm, khoảng 2/3 ly)\\n- Nước sôi ~80°C → sau cho nước nguội còn ~50°C\\nPhục vụ: gây chú ý với khách, bật đèn cá nhân, cảnh báo nóng", keywords: ["mỳ", "phở", "nước nóng", "80°C", "50°C", "hạng Y"], category: "Dịch vụ" },
  { id: 112, question: "(DV CÂU 16) Chuẩn bị thức uống nóng hạng Y? TCPV 3.1.20", answer: "TRÀ: tép trà + 3/4 nước nóng → 3-5 phút → lấy tép ra → 1/4 nước nguội → ~70°C\\nCÀ PHÊ: cafe + ít nước nóng lắc nhẹ → đổ thêm đến 3/4 → 1/4 nước nguội → ~70°C\\nCách miệng bình 5cm, miệng tách nhỏ 1cm, tách lớn 3cm\\nHạng C: pha đậm nhạt theo yêu cầu\\nHạng Y nội địa: 1 gói 30g/1 bình xanh, quốc tế: 2/3 gói 30g/1 bình xanh", keywords: ["trà", "cà phê", "70°C", "nước nóng", "thức uống", "hạng Y"], category: "Dịch vụ" },
  { id: 113, question: "(DV CÂU 17) Cung ứng suất ăn đường bay KUL? (HalAL)", answer: "SGN/HAN-KUL-HAN/SGN: suất ăn HalAL (đạo Hồi) được cung ứng cho toàn bộ hành khách", keywords: ["KUL", "HalAL", "đạo Hồi", "suất ăn"], category: "Dịch vụ" },
  { id: 114, question: "(DV CÂU 44) Rượu Champagne - giới thiệu và cách phục vụ?", answer: "- Sản xuất từ nho vùng Champagne, Pháp\\n- Rượu sủi tăm màu trắng\\n- 3 giống nho: Pinot Noir, Pinot Meunier, Chardonnay\\n- Nồng độ cồn: 12%\\n- Nhiệt độ: 7-10°C\\n- Dùng làm khai vị hoặc món khai vị, phô mai, trái cây", keywords: ["champagne", "rượu", "12%", "7-10°C", "Pinot", "Chardonnay"], category: "Dịch vụ" },
  { id: 115, question: "(DV CÂU 45) Rượu Bailey's Irish Cream?", answer: "- Xuất xứ: Ireland\\n- Nồng độ cồn: 17%\\n- Nền whiskey + cà phê, kem, sữa\\n- Rượu mùi: 25-55%, hương trái cây, kem, thảo mộc\\n- Phục vụ: ly rượu mạnh, rót hết 01 chai vào ly", keywords: ["Bailey", "rượu mùi", "17%", "whiskey", "Ireland"], category: "Dịch vụ" },
  { id: 116, question: "(DV CÂU 46-48) Rượu Remy Martin, Drambuie, Rhum?", answer: "REMY MARTIN: Cognac, 40%, màu vàng sáng, hương mơ đào vani\\nDRAMBUIE: Scotland, 40%, màu vàng, 15-17 năm tuổi, hương mật ong thảo mộc\\nRHUM: Cuba, 37.5%, chưng cất từ mía, 4 loại: Light – Medium – Full – Aromatic\\nPhục vụ: ly rượu brandy/mạnh, rót hết 01 chai", keywords: ["Remy Martin", "Drambuie", "Rhum", "Scotland", "Cuba", "cognac"], category: "Dịch vụ" },
  { id: 117, question: "(DV CÂU 49) Rượu Sake?", answer: "- Từ gạo lên men, Nhật Bản\\n- Nồng độ: 15-16%\\n- Dùng khai vị hoặc món chính\\n- Sake lạnh 10°C, Sake nóng 50°C", keywords: ["sake", "rượu Nhật", "gạo", "15-16%", "10°C", "50°C"], category: "Dịch vụ" },
  { id: 118, question: "(DV CÂU 50) Welcome drink hạng C? TCPV 4.1.6.2", answer: "- Phục vụ theo yêu cầu từng khách\\n- Ướp lạnh, rót sẵn 50% số khách\\n- Nước trái cây: 1/2 ly (2/3 ly loại cũ), Champagne: 1/3 ly\\n- Đường bay trung/dài: on demand\\n- Đường bay ngắn/A321: on tray", keywords: ["welcome drink", "hạng C", "champagne", "on demand", "on tray"], category: "Dịch vụ" },
  { id: 119, question: "(DV CÂU 53-54) Các loại trà và cà phê hạng C?", answer: "TRÀ: Xanh VN (nhài/sen), Xanh Nhật, Bạc hà, English Breakfast, Earl Grey, Hương trái cây, Thảo mộc\\nCÀ PHÊ: Đen, Phin giấy, Espresso, Cappuccino, Latte, Americano, Sữa đá/nóng VN, Bạc xỉu", keywords: ["trà", "cà phê", "hạng C", "Earl Grey", "espresso", "cappuccino", "latte"], category: "Dịch vụ" },
  { id: 120, question: "(DV CÂU 55) Cách sắp xếp khăn bông hạng C? TCPV 4.1.6.2", answer: "- Khăn nóng: nhiệt độ ngoài < 20°C / Khăn lạnh: >= 20°C\\n- Kiểm tra độ nóng trước khi mời\\n- Giỏ mây có lót, tối đa 10 khăn/giỏ xếp ngay ngắn\\n- Gắp vàng (mời khăn) – Gắp xanh (thu khăn)\\n- Nướng: mở foil, cho nước nóng, bọc lại, STEAM 10-15 phút", keywords: ["khăn bông", "gắp vàng", "gắp xanh", "STEAM", "10-15 phút"], category: "Dịch vụ" },
  { id: 121, question: "(DV CÂU 58) Nhiệt độ phục vụ vang đỏ & vang trắng?", answer: "VANG ĐỎ: 12-17°C, phù hợp thịt đỏ/trắng, nướng, bò, cừu, mỳ Ý, phô mai\\nVANG TRẮNG: 7-8°C, phù hợp cá, hải sản, thịt trắng", keywords: ["vang đỏ", "vang trắng", "wine", "12-17°C", "7-8°C", "nhiệt độ"], category: "Dịch vụ" },
  { id: 122, question: "(DV CÂU 78-81) Signature Drink và Cocktail VNA hạng C?", answer: "SIGNATURE DRINK:\\n- CÁT HỒNG PHAN THIẾT: Rhum + Campari + Nước cam\\n- ĐẤT PHƯƠNG NAM: Whisky + Campari + Nước chanh + Nước đường\\n- MIỀN ĐẠI NGÀN: Vang đỏ + Rhum + Nước cam + Nước táo\\nCOCKTAIL NỀN VANG:\\n- WINE COOLER: White wine + 7up + chanh\\n- SPRITZER: White wine + soda\\n- HẢI ĐẢO YÊU THƯƠNG: White wine + Ginger Ale + Blue Curacao\\nCOCKTAIL NỀN CAMPARI:\\n- GARIBALDI: Campari + Nước cam\\n- TROPICAL DAWN: Campari + Gin + Nước cam\\n- GENOA: Campari + Vodka + Nước cam\\n- HELLO VIỆT NAM: Campari + Nước cam + Sprite\\n- SÔNG HỒNG: Whisky + Dry Martini + Nước cam\\nTrang trí Y: Tea color = no garnish, Yellow/orange = orange & cherry, Colorless = lemon/oliu, Campari base = orange", keywords: ["cocktail", "signature drink", "Cát Hồng", "Đất Phương Nam", "Miền Đại Ngàn", "Wine Cooler", "Campari"], category: "Dịch vụ" },
  { id: 123, question: "(DV CÂU 82) Phục vụ bà mẹ có trẻ em đi cùng?", answer: "Boarding: giúp đỡ vào chỗ ngồi, giới thiệu tên, thông báo dịch vụ nôi, hướng dẫn nhà vệ sinh bàn thay tã\\nTrên CB: chủ động chăm sóc, pha sữa, phục vụ BBML/CHML trước hoặc theo yêu cầu\\nGiảm độ cao: thu nôi, dọn rác, thông báo nhiệt độ điểm đến, lấy áo ấm cho trẻ\\nSau khi đáp: trợ giúp hành lý, di chuyển xuống", keywords: ["bà mẹ", "trẻ em", "nôi", "BBML", "CHML", "chăm sóc"], category: "Dịch vụ" },
  { id: 124, question: "(DV CÂU 84) Nguyên tắc xử lý tình huống bất thường? TCPV 6.1", answer: "- Luôn giữ bình tĩnh, thái độ tích cực\\n- Nhận biết sự hiện diện, chào hỏi lịch sự, gọi tên khách\\n- Lắng nghe chủ động, tạo cơ hội bộc phát bực tức\\n- Đặt câu hỏi để hiểu nhu cầu\\n- Biểu hiện cảm thông: 'Tôi hiểu được ý của ông/bà'\\n- Duy trì bình tĩnh và tôn trọng, đề xuất giúp đỡ\\n- Giải thích và nhắc lại\\n- Nếu không đáp ứng được: gợi ý lựa chọn khác, xin lỗi", keywords: ["tình huống", "bất thường", "bình tĩnh", "lắng nghe", "cảm thông", "xin lỗi"], category: "Dịch vụ" },
  { id: 125, question: "(DV CÂU 85) Xưng hô với khách bằng tên và chức danh?", answer: "Thể hiện sự kính trọng, cho thấy bản thân lịch sự\\nTần suất:\\n- Hạng C: ít nhất 4 lần/chuyến (TVT giới thiệu 1 lần, phục vụ 2 lần, cuối chuyến 1 lần)\\n- Hạng PE và Y: chào gọi tên tại cửa máy bay (50% PE / 30-40% Y)", keywords: ["gọi tên", "xưng hô", "4 lần", "hạng C", "tên khách"], category: "Dịch vụ" },
  { id: 126, question: "(DV CÂU 87) TVT nhận giấy tờ gì đầu chuyến?", answer: "- GD: Danh sách tổ bay\\n- PM: Danh sách hành khách\\n- Loadsheet: Bảng cân bằng trọng tải\\n- Passenger Special Information\\n- Cargo Manifest\\n- Các giấy tờ khác từ TCT liên quan chuyến bay", keywords: ["giấy tờ", "GD", "PM", "loadsheet", "cargo manifest"], category: "Dịch vụ" },
  { id: 127, question: "(DV CÂU 88) Kỹ năng khi boarding?", answer: "- Chào đón và gọi tên hành khách\\n- Kiểm tra boarding pass\\n- Giúp đỡ tìm ghế và sắp xếp hành lý\\n- Giám sát khu vực phụ trách\\n- Hỗ trợ khách cao tuổi, trẻ em, bà mẹ, phụ nữ có thai\\n- Xử lý tình huống phát sinh\\n- Nhận diện hành lý xách tay quá quy định", keywords: ["boarding", "chào đón", "boarding pass", "hành lý", "giám sát"], category: "Dịch vụ" },
  { id: 128, question: "(DV CÂU 89) Tiêu chuẩn khoang khách trước Boarding? TCPV 3.2.1", answer: "- Thảm sạch, khô ráo, không mùi\\n- Ghế ngồi ngay ngắn, dây an toàn bắt chéo, lưng dựng thẳng\\n- Túi ghế: túi nôn, Safety card, Heritage, Heritage Fashion, BHMT, CTGT\\n- Hộc tủ sạch gọn, nặng dưới nhẹ trên\\n- Tủ treo áo: sạch thơm, đủ mắc áo + tag\\n- Nhiệt độ: 22°C (mùa hè), 25°C (mùa đông)\\n- Chăn/gối đúng vị trí, logo ra ngoài\\n- Đèn: A321 FULL, A350 MANUAL, B787 BOARDING/DEPLANE", keywords: ["khoang khách", "boarding", "tiêu chuẩn", "túi ghế", "Safety card", "đèn"], category: "Dịch vụ" },
  { id: 129, question: "(DV CÂU 100) 4 hạng mục giá trị?", answer: "1/ Sản phẩm chủ đạo: lý do chính khách hàng đến\\n2/ Sự thuận tiện: quy trình, công cụ cung cấp DV tiện lợi\\n3/ Tư duy dịch vụ: thái độ, tinh thần chuyên nghiệp, sự cảm thông\\n4/ Phát triển mối quan hệ: kết nối, duy trì, phát triển quan hệ với khách hàng", keywords: ["giá trị", "sản phẩm", "thuận tiện", "tư duy dịch vụ", "mối quan hệ"], category: "Dịch vụ" },
  { id: 130, question: "(DV CÂU 101) 6 cấp độ dịch vụ?", answer: "1/ Criminal (Tồi tệ): phá vỡ cam kết, khách không bao giờ quay lại\\n2/ Basic (Không vui): mức tối thiểu, khách sẽ tránh xa\\n3/ Expected (Bình thường): không đặc biệt, chỉ quay lại khi không có lựa chọn\\n4/ Desired (Mong muốn): đúng sở thích, kéo khách quay lại\\n5/ Surprising (Ngạc nhiên): đặc biệt, nhiều hơn mong muốn, khách kể bạn bè\\n6/ Unbelievable (Trên cả tuyệt vời): gây sửng sốt, trở thành huyền thoại\\nDỊCH VỤ XUẤT SẮC: Liên tục tạo giá trị mới, biết cấp độ của mình và hành động lên cao hơn", keywords: ["6 cấp độ", "dịch vụ", "criminal", "basic", "expected", "desired", "surprising", "unbelievable"], category: "Dịch vụ" },
  { id: 131, question: "(DV CÂU 102-104) 6 nhu cầu, 5 giá trị cốt lõi, 5 nguyên tắc hành động?", answer: "6 NHU CẦU KHÁCH HÀNG: Flight/bio safety & security, Timeliness, Cost, Services and Quality, Prompt action, Appreciation and status\\n5 GIÁ TRỊ CỐT LÕI:\\n1. Đặt CON NGƯỜI làm ưu tiên hàng đầu\\n2. Hành động với sự CHÍNH TRỰC\\n3. Theo đuổi sự XUẤT SẮC\\n4. Hướng tới sự QUAN TÂM\\n5. Duy trì và phát huy BẢN SẮC VĂN HOÁ VIỆT\\n5 NGUYÊN TẮC HÀNH ĐỘNG:\\n1. Chú ý ngoại hình, ngôn ngữ, thái độ tích cực\\n2. Cam kết TÔI CÓ THỂ, chịu trách nhiệm cá nhân\\n3. Tạo môi trường làm việc tích cực\\n4. Tự hào là phần của Vietnam Airlines\\n5. Lắng nghe, thấu hiểu, đồng cảm", keywords: ["nhu cầu", "giá trị cốt lõi", "nguyên tắc", "HEART", "con người", "chính trực", "xuất sắc"], category: "Dịch vụ" },
  { id: 132, question: "(DV CÂU 121) Các loại ly thuỷ tinh hạng C?", answer: "- Ly giải khát nhỏ: nước trái cây, ga, bia, rượu pha (cách miệng 2cm)\\n- Ly giải khát to: tương tự (Welcome drink rót 1/2)\\n- Ly rượu vang nhỏ: vang trắng/đỏ/hồng (1/2 ly), nước suối/champagne (cách 2cm), vang mạnh/sake (1/3 ly)\\n- Ly rượu vang to: 1/3 ly\\n- Ly rượu mạnh: rượu mạnh, rượu mùi, sake (1/3 ly)\\n- Ly Brandy: Brandy uống thẳng/đúp (1/3 từ đáy)\\n- Ly Champagne: 1/3 ly", keywords: ["ly", "thuỷ tinh", "hạng C", "rượu vang", "brandy", "champagne"], category: "Dịch vụ" },
  { id: 133, question: "(DV CÂU 124) Xử lý khách có dấu hiệu say rượu?", answer: "- Lưu ý khách đã uống nhiều với thái độ nhẹ nhàng lịch sự\\n- Thông báo vì sức khoẻ, TV tạm ngưng phục vụ cồn sau 1-2h\\n- Mời thức ăn nhẹ (hạt rang, bánh mỳ, phomai) + đồ uống không cồn\\n- Báo cáo TVT, thông báo các TV khác\\n- Đánh giá mức độ say để xử trí phù hợp\\n- Thường xuyên chăm sóc trong suốt chuyến bay", keywords: ["say rượu", "đồ uống có cồn", "tạm ngưng", "intoxicated"], category: "Dịch vụ" },
  { id: 134, question: "Phục hồi dịch vụ là gì? Đảm bảo dịch vụ là gì?", answer: "PHỤC HỒI DỊCH VỤ: Là quá trình ghi nhận, phát hiện và xử lý lỗi phát sinh thuộc trách nhiệm VNA trong quá trình cung cấp DV đến khách hàng\\nĐẢM BẢO DỊCH VỤ: Là sự cam kết của VNA về việc thực hiện hoạt động phục hồi mỗi khi có lỗi\\nMỤC ĐÍCH: Tạo trải nghiệm vui vẻ, xoa dịu bực bội, lấy lại niềm tin, gắn kết khách hàng\\nGIỚI HẠN:\\n- Không áp dụng khách nội bộ (vé ID, vé giảm)\\n- Không áp dụng chuyến bay thuê chuyến", keywords: ["phục hồi", "đảm bảo dịch vụ", "bồi thường", "service recovery", "gắn kết"], category: "Phục hồi & Bồi thường" },
  { id: 135, question: "Quy trình thực hiện bồi thường gắn kết?", answer: "1/ TVT trao quyền cho TV cung cấp thêm giá trị\\n2/ TVT đề xuất để khách lựa chọn hình thức bồi thường\\n3/ TV điền phiếu 'Ghi nhận thông tin phục hồi và đảm bảo dịch vụ'\\n4/ Gửi khách 1 liên, xuất trình tại chi nhánh/phòng vé VNA\\n5/ Dặm thưởng cộng vào tài khoản sau 5-7 ngày\\nLƯU Ý:\\n- Bồi thường gắn kết ≠ MCO\\n- Tận dụng phương tiện/sản phẩm sẵn có trên chuyến bay\\n- Công cụ bồi thường hạng Y < C (cùng mức độ lỗi)\\n- Cộng dặm thưởng chỉ cho hội viên Bông Sen Vàng\\n- TVT có thể áp dụng mức thấp hơn tối đa\\n- TVT viết BCCB, lập biên bản vụ việc", keywords: ["quy trình", "bồi thường gắn kết", "phiếu", "dặm thưởng", "Bông Sen Vàng", "5-7 ngày"], category: "Phục hồi & Bồi thường" },
  { id: 136, question: "Mức độ lỗi và các lỗi cụ thể - Level 1 đến Level 4?", answer: "LEVEL 1 - LỖI NHỎ: Khách chưa hài lòng, bất tiện nhỏ\\n- Món ăn quá mặn/nhạt, vỏ ghế rách/bẩn/bạc màu, thảm bẩn\\n- Thái độ TV không thân thiện, chu đáo\\n→ Không bồi thường, tập trung xin lỗi và quan tâm\\n\\nLEVEL 2 - LỖI VỪA PHẢI: Khách không hài lòng, cảm xúc tiêu cực\\n- TV có thái độ không đúng mực, không tôn trọng\\n- Suất ăn ôi thiu, quá hạn, biến dạng\\n→ Khách ưu tiên: 2000 dặm / 01 kiện 23kg / 10% discount\\n→ Khách phổ thông: 1000 dặm / 5% discount\\n\\nLEVEL 3 - LỖI LỚN: Khách chịu gián đoạn, thiệt hại\\n- HTGT hư hỏng + cảm xúc tiêu cực leo thang\\n- Suất ăn có vật lạ nguy hiểm, TV làm đổ đồ nóng gây bỏng\\n→ Khách ưu tiên: 4000 dặm / 01 kiện 32kg / 15% discount / Thẻ mời phòng khách Business / Nâng hạng dịch vụ\\n→ Khách phổ thông: 2000 dặm / 01 kiện 23kg / 10% discount / Thẻ mời phòng khách Business\\n\\nLEVEL 4 - LỖI NGHIÊM TRỌNG: Thiệt hại lớn về thể chất, tinh thần, tài chính\\n- TV phục vụ gây dị ứng dù đã thông báo trước → đe doạ tính mạng\\n- Khách bỏng nghiêm trọng\\n- Suất ăn có vật lạ gây nguy hiểm cho hành khách\\n→ Khách ưu tiên: 6000 dặm / 02 kiện 32kg / 20% discount / Thẻ mời phòng khách Business / Nâng hạng dịch vụ\\n→ Khách phổ thông: 4000 dặm / 02 kiện 23kg / 15% discount / Thẻ mời phòng khách Business / Nâng hạng dịch vụ", keywords: ["level 1", "level 2", "level 3", "level 4", "mức độ lỗi", "dặm thưởng", "discount", "nâng hạng", "bồi thường", "vật lạ", "bỏng", "dị ứng"], category: "Phục hồi & Bồi thường" },
  { id: 137, question: "Quy trình thực hiện phục hồi và đảm bảo dịch vụ?", answer: "1/ Nhận diện lỗi: TV tiếp xúc khách để xem phản ứng và cảm xúc\\n2/ Đánh giá mức độ lỗi: dựa vào bảng mức độ lỗi\\n3/ Thực hiện khắc phục: Nếu liên quan trang thiết bị nội thất → dùng MCO (không dùng bồi thường gắn kết)\\n4/ Cung cấp thêm giá trị mới → bồi thường gắn kết:\\n- TVT dựa vào bảng công cụ bồi thường\\n- TVT đề xuất 1 hình thức (VD cộng dặm cho hội viên BSV)\\n- TVT có thể nâng hạng ngay trên chuyến bay\\n5/ Điền phiếu: TVT giao khách liên 01, giữ liên 02 nộp ĐTV + ghi BCCB", keywords: ["quy trình phục hồi", "nhận diện lỗi", "đánh giá", "khắc phục", "MCO", "phiếu"], category: "Phục hồi & Bồi thường" },
  { id: 138, question: "Bồi thường MCO (Miscellaneous Charge Order) - Trang thiết bị nội thất?", answer: "MCO = Chứng từ thanh toán DV vận chuyển hàng không đa mục đích\\n- Áp dụng cho khách trên chuyến bay VNA khai thác\\n- Khách được xếp vào vị trí 'bồi thường cho hành khách'\\n- Không áp dụng vé ID\\n- Có thể linh hoạt thanh toán tiền mặt/chuyển khoản (= 2/3 MCO)\\n- Khách xuất trình tại đại diện VNA/chi nhánh trong 30 ngày\\n\\nCÁC LỖI ĐƯỢC BỒI THƯỜNG MCO:\\n1. Hạng C - Chức năng ngả/dựng lưng ghế: Không hoạt động\\n2. Hạng C - Chức năng duỗi chân ghế: Không hoạt động\\n3. Hạng PE - Ngả/dựng lưng ghế: Không hoạt động\\n4. Hạng C - Màn hình cá nhân: Không hoạt động\\n5. Hạng C - PCU điều khiển giải trí: Mất/không hoạt động\\n6. Hạng C - Hệ thống âm thanh: Không hoạt động\\n7. Hạng C - Màn hình chung (không Inseat Video): Không hoạt động\\n8. Hạng PE - Màn hình cá nhân: Không hoạt động\\n9. Hạng PE - PCU: Mất/không hoạt động\\n10. Hạng PE - Hệ thống âm thanh: Không hoạt động\\n11. Hạng C - Toilet (2-4h): Bồn cầu vỡ/tắc, vòi nước hỏng, thoát nước tắc, cửa/đèn hỏng\\n12. Hạng Y (FT >9h) - Ngả/dựng lưng ghế: Không hoạt động", keywords: ["MCO", "bồi thường", "trang thiết bị", "nội thất", "IFE", "ghế", "màn hình", "toilet", "PCU"], category: "Phục hồi & Bồi thường" },
  { id: 139, question: "Mức bồi thường MCO - Quốc tế và Quốc nội?", answer: "QUỐC TẾ (Hạng C):\\n- Mức 1: 300 USD (Châu Âu, Mỹ, Úc, Nhật, Hàn)\\n- Mức 2: 200 USD (HKG, Đài Loan, China, SIN, KUL, CGK, MNL, các đường bay khác)\\n- Mức 3: 100 USD (Xuyên Đông Dương)\\n- Mức 4: 50 USD (toilet hạng C)\\nQUỐC NỘI (Hạng C):\\n- Mức 1: 800.000 VND (HAN-SGN/VCA/PQC)\\n- Mức 2: 600.000 VND (HAN/SGN-HUI/DAD/CXR/UIH/VCL, SGN-VDO/VDH/VII)\\n- Mức 3: 400.000 VND (SGN-HPH, HAN-TBB/BMV/DLI/PXU, các chặng khác)\\n- Mức 4: 200.000 VND (toilet)\\nHẠNG PE: 100 USD/khách (quốc tế)\\nHẠNG Y: 70 USD/khách (quốc tế)\\n\\nGIÁ TRỊ TIỀN MẶT (2/3 MCO):\\nQuốc tế: 300→200, 200→135, 100→70, 70→50, 50→35 USD\\nQuốc nội: 800K→550K, 600K→400K, 400K→270K, 200K→150K VND\\n\\nĐỊNH MỨC PHIẾU: A350/B787 = 20 phiếu (2 chiều), A321 = 10 phiếu, ATR72 = 5 phiếu", keywords: ["MCO", "mức bồi thường", "300 USD", "200 USD", "100 USD", "800.000 VND", "tiền mặt", "2/3 MCO", "phiếu"], category: "Phục hồi & Bồi thường" },
  { id: 140, question: "(XLTH CÂU 115) Khách bị bệnh trên chuyến bay - Bộ XLTH FIX-CARE-ADD?", answer: "FIX:\\n- TV nhận thông tin từ khách, thông báo TVT ngay\\n- Hỏi thăm tiền sử bệnh lý, thuốc mang theo\\n- Kêu gọi hỗ trợ bác sĩ trên chuyến bay\\n- TV hỗ trợ bác sĩ (FAK, bình oxy) → Báo cáo PIC\\n- TVT lập BB sức khoẻ bất thường\\nCARE:\\n- TVT phân công TV theo dõi chăm sóc khách\\n- Liên hệ NVMĐ/Đại diện/y tế sân bay\\nADD:\\n- Liên hệ người nhà/khách hỏi thăm sức khoẻ\\n- Gửi hoa chúc sức khỏe / đến bệnh viện thăm", keywords: ["bệnh", "FIX", "CARE", "ADD", "bác sĩ", "FAK", "bình oxy", "sức khoẻ"], category: "Phục hồi & Bồi thường" },
  { id: 141, question: "(XLTH CÂU 116) Chuyến bay trễ do kỹ thuật, đổi máy bay - FIX-CARE-ADD?", answer: "FIX:\\n- Nhận diện tiếp cận ngay khách không thoải mái\\n- Ghi nhận ý kiến với thái độ nghiêm túc, cầu thị\\n- Đồng cảm: 'Em hoàn toàn đồng ý/em hiểu…'\\n- Xin lỗi chân thành, mời khách về chỗ\\n- Phục vụ đúng yêu cầu, báo cáo TVT\\nCARE:\\n- Hướng dẫn tiện ích tại ghế\\n- Kiểm tra mức độ hài lòng\\n- Thường xuyên hỏi thăm, nhớ sở thích\\nADD:\\n- Quan tâm chăm sóc hơn nữa\\n- Tặng DV đặc biệt/quà có logo VNA\\n- Tặng Phiếu bồi thường gắn kết nếu phản ứng gay gắt", keywords: ["delay", "trễ", "kỹ thuật", "FIX", "CARE", "ADD", "đồng cảm", "bồi thường gắn kết"], category: "Phục hồi & Bồi thường" },
  { id: 142, question: "(XLTH CÂU 117) Khách sợ trễ chuyến bay nối chuyến - FIX-CARE-ADD?", answer: "FIX:\\n- Tiếp cận ngay, lắng nghe thấu hiểu\\n- Mẫu câu: 'Em hiểu rằng + giá trị khách mong muốn'\\n- Xin lỗi chân thành\\n- Nhận thông tin CB nối chuyến (xem vé), hỏi đi cùng ai\\n- Báo cáo TVT → TVT báo NVMĐ\\nCARE:\\n- Chăm sóc chu đáo suốt CB\\n- Mời xem chương trình giải trí, Air show\\nADD:\\n- Mời thức uống hạng C\\n- Đổi chỗ lên phía trước khi sắp hạ cánh\\n- Hỗ trợ hành lý, chúc hành trình tốt đẹp", keywords: ["nối chuyến", "connecting flight", "trễ", "FIX", "CARE", "ADD", "đổi chỗ"], category: "Phục hồi & Bồi thường" },
  { id: 143, question: "(XLTH CÂU 118-119) Khách bấm nút gọi TV nhưng không ai đến / Quên phục vụ?", answer: "Khách bấm nút gọi TV:\\n- Xin lỗi về sự chậm trễ\\n- Tìm hiểu nhu cầu, đáp ứng ngay\\n- Cảm ơn khách đã chờ đợi, xin lỗi lần nữa\\n- Thường xuyên chăm sóc suốt CB\\n- Báo cáo TVT để ra hỏi thăm xin lỗi\\n- TVT de-briefing/coaching với tổ TV\\n\\nQuên phục vụ suất ăn/đồ uống:\\n- Xin lỗi chân thành về chậm trễ\\n- Hỏi yêu cầu và đáp ứng nhanh nhất + hỏi thêm yêu cầu khác\\n- Thường xuyên quan sát, chăm sóc, tìm cơ hội phục vụ tốt hơn\\n- Báo cáo TVT", keywords: ["nút gọi", "chậm trễ", "quên phục vụ", "xin lỗi", "de-briefing", "coaching"], category: "Phục hồi & Bồi thường" }
];